content:
{
  "items": [
    {
      "slot": 1,
      "description": "Match a French mobile phone number in the national format. It must start with 06 or 07, followed by eight digits. The digits may optionally be separated by single spaces or hyphens, but only between digits, and the number must not start or end with a separator.",
      "regex": "/^0[67](?:[ .-]?\\d){8}$/"
    },
    {
      "slot": 2,
      "description": "french mobile number with optional spaces hyphens or dots between digits",
      "regex": "/^0[67](?:[ .-]?\\d){8}$/"
    },
    {
      "slot": 3,
      "description": "Our CRM stores French phone numbers. We need to validate that a number is a valid French landline or mobile number in the national format. It must have exactly 10 digits, starting with 0. The second digit can be 1 through 9 for landlines, or 6 or 7 for mobiles. Spaces, hyphens and dots are allowed as separators but only between digits, and there should be no separator at the very beginning or end.",
      "regex": "/^0(?:[1-59](?:[ .-]?\\d){8}|[67](?:[ .-]?\\d){8})$/"
    },
    {
      "slot": 4,
      "description": "french mobile number without separators",
      "regex": "/^0[67]\\d{8}$/"
    },
    {
      "slot": 5,
      "description": "Match an international phone number in E.164 format. It must start with a plus sign, followed by a non-zero digit, and then up to 14 more digits. The total number of digits after the plus must be between 2 and 15.",
      "regex": "/^\\+[1-9]\\d{1,14}$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "A price in euros using French formatting: digits may be grouped by spaces in threes, the decimal separator is a comma, and the euro sign follows the number with no space.",
      "regex": "/^\\d{1,3}(?: \\d{3})*(?:,\\d{2})?€$/"
    },
    {
      "slot": 2,
      "description": "A US dollar amount. The number must start with a dollar sign, followed by digits; cents are optional and, if present, must be exactly two digits after a dot. The integer part may include commas as thousands separators, but only if they are correctly placed every three digits.",
      "regex": "/^\\$(?:\\d{1,3}(?:,\\d{3})*|\\d+)(?:\\.\\d{2})?$/"
    },
    {
      "slot": 3,
      "description": "euro price french format comma decimal space thousands trailing €, integer part must have at least one group of three digits unless the whole integer is a single digit zero",
      "regex": "/^(?:0|\\d{1,3}(?: \\d{3})+)(?:,\\d{2})?€$/"
    },
    {
      "slot": 4,
      "description": "Our checkout page accepts prices that are entered with a three-letter currency code from the ISO 4217 standard before the amount. The amount must use exactly two digits after the decimal point; the decimal point is a dot, and the integer part must be at least one digit and may contain commas as thousands separators, but only if every group after the first has exactly three digits.",
      "regex": "/^[A-Z]{3}\\d{1,3}(?:,\\d{3})*\\.\\d{2}$/"
    },
    {
      "slot": 5,
      "description": "For our internal accounting export, we need to validate strings that represent prices. A price is written with digits, an optional euro sign at the beginning, and exactly two decimal places separated by a dot. The integer part must not have a leading zero unless the value is between zero and one, in which case a single zero is required before the dot.",
      "regex": "/^€?(?:0|[1-9]\\d*)\\.\\d{2}$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "pin code 4 to 6 digits not all the same",
      "regex": "/^(?!^(\\d)\\1+$)\\d{4,6}$/"
    },
    {
      "slot": 2,
      "description": "API key must start with the prefix 'sk_live_' followed by exactly 24 alphanumeric characters (case-sensitive).",
      "regex": "/^sk_live_[A-Za-z0-9]{24}$/"
    },
    {
      "slot": 3,
      "description": "A passphrase must consist of at least four words separated by a single space. Each word must contain at least one character and consist only of lowercase letters (a-z).",
      "regex": "/^[a-z]+(?: [a-z]+){3,}$/"
    },
    {
      "slot": 4,
      "description": "A password is valid if it is at least 8 characters long and does not contain the substring 'password' anywhere. The check is case-insensitive.",
      "regex": "/^(?=.{8,}$)(?!.*password).*$/i"
    },
    {
      "slot": 5,
      "description": "For our internal API, we need to validate secret keys. The format must start with the prefix 'api_' followed by exactly 32 hexadecimal digits (0-9, a-f).",
      "regex": "/^api_[0-9a-f]{32}$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "Match a semantic version string with optional pre-release and build metadata. The main version consists of three dot-separated numeric identifiers without leading zeros. Pre-release is a hyphen followed by one or more dot-separated identifiers, each containing only alphanumeric characters and hyphens, and numeric identifiers must not have leading zeros. Build metadata is a plus sign followed by one or more dot-separated identifiers of alphanumeric characters and hyphens.",
      "regex": "/^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-((?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\\.(?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\\+([0-9a-zA-Z-]+(?:\\.[0-9a-zA-Z-]+)*))?$/"
    },
    {
      "slot": 2,
      "description": "Our software releases use a year.month version where the year is four digits and the month is two digits from 01 to 12. The release field in our database must accept exactly this format with no leading zeros in the year part.",
      "regex": "/^(\\d{4})\\.(0[1-9]|1[0-2])$/"
    },
    {
      "slot": 3,
      "description": "We require semantic versioning for all our npm packages. A valid version is exactly three dot-separated numeric parts. The major, minor, and patch numbers must not have leading zeros unless the number is zero itself. Pre-release and build metadata are not allowed in this context.",
      "regex": "/^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)$/"
    },
    {
      "slot": 4,
      "description": "python version specifier like ==1.2.3 or >=2.0.1,<3.0.0",
      "regex": "/^(?:[<>=!~]=?|~=)?\\d+(?:\\.\\d+)*(?:\\.[*xX])?(?:, *(?:[<>=!~]=?|~=)?\\d+(?:\\.\\d+)*(?:\\.[*xX])?)*$/"
    },
    {
      "slot": 5,
      "description": "Match a Python version specifier that is exactly a version number or a simple comparison operator (==, !=, <=, >=, <, >) followed by a version number. Pre-release or local version labels are not allowed.",
      "regex": "/^(?:(?:==|!=|<=|>=|<|>)?\\d+(?:\\.\\d+)*)$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "A CSS length value as a string: an optional sign (+ or -), one or more decimal digits, an optional fractional part consisting of a dot and one or more digits, followed by a unit. The unit must be one of the following, case-insensitively: px, em, rem, vw, vh, cm, mm, in, pt, pc. No whitespace is allowed anywhere.",
      "regex": "/^[+-]?\\d+(\\.\\d+)?(px|em|rem|vw|vh|cm|mm|in|pt|pc)$/i"
    },
    {
      "slot": 2,
      "description": "In our HTML sanitizer, we need to detect opening tags for the custom element 'custom-card'. A valid opening tag must start with '<custom-card' followed by either a '>' or at least one whitespace character before any attributes and the closing '>'. The tag name must be exactly 'custom-card' (case-sensitive). Attributes are allowed after the whitespace; the tag may end with '>' or '/>'. The match must cover the entire string.",
      "regex": "/^<custom-card(?:\\s[^>]*)?\\/?>$/"
    },
    {
      "slot": 3,
      "description": "A data URI string that encodes an image. It must start with 'data:image/' (case-insensitive) followed by one or more characters that are not ';' or ',', then either ';base64,' followed by one or more base64 characters (A-Z, a-z, 0-9, +, /, =) or just ',' followed by one or more characters that are not ','. The entire string must match.",
      "regex": "/^data:image\\/[^;,\\s]+(?:;base64,[A-Za-z0-9+/=]+|,[^,]+)$/i"
    },
    {
      "slot": 4,
      "description": "Match a URL that starts with either http:// or https:// (case-insensitive). It must contain a host that consists of one or more labels separated by dots, where each label is one or more alphanumeric characters or hyphens (but cannot start or end with a hyphen). The host must end with a dot and a top-level domain of at least two letters. The host may be followed by an optional port number (one or more digits) and an optional path, query string, and fragment. The entire string must be a valid URL according to this description.",
      "regex": "/^https?:\\/\\/(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\\.)+[a-z]{2,}(?::\\d+)?(?:\\/[^\\s]*)?(?:\\?[^\\s#]*)?(?:#[^\\s]*)?$/i"
    },
    {
      "slot": 5,
      "description": "Our design system accepts CSS length values in the following units: px, em, rem, vh, vw, and %. The value may be a positive or negative integer or decimal number. If a decimal point is present, there must be at least one digit before and after it. Leading zeros are not required. No spaces or other characters are allowed. The unit is required.",
      "regex": "/^[+-]?(?:\\d+(?:\\.\\d+)?|\\.\\d+)(px|em|rem|vh|vw|%)$/i"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "Validate a string representing an integer from 0 to 255 inclusive. The string must consist only of digits and cannot have leading zeros unless it is exactly '0'. No other characters, signs, or whitespace are allowed.",
      "regex": "/^(?:0|1[0-9]{0,2}|2[0-4][0-9]|25[0-5])$/"
    },
    {
      "slot": 2,
      "description": "Validate a number written in scientific notation. The number may start with an optional minus sign, followed by a mantissa that is either an integer or a decimal with exactly one digit before and at least one digit after the decimal point. The mantissa must be followed by 'e' or 'E', an optional plus or minus sign, and one or more digits for the exponent. No spaces or other characters allowed.",
      "regex": "/^-?(?:\\d+(?:\\.\\d+)?|\\.\\d+)[eE][+-]?\\d+$/"
    },
    {
      "slot": 3,
      "description": "Rule 1: The number may be prefixed with an optional '+' or '-'. Rule 2: The integer part must be one or more digits. Rule 3: If a decimal point is present, it must be followed by one or more digits. Rule 4: No leading zeros are allowed in the integer part unless the integer part is exactly '0'. Rule 5: No spaces or thousands separators are allowed.",
      "regex": "/^[+-]?(?:0|[1-9]\\d*)(?:\\.\\d+)?$/"
    },
    {
      "slot": 4,
      "description": "We're building a configuration panel where users enter network octets. Each octet must be a whole number from 0 up to and including 255. Users should type just the digits, no signs, spaces, or leading zeros.",
      "regex": "/^(?:0|1\\d{0,2}|2[0-4]\\d|25[0-5])$/"
    },
    {
      "slot": 5,
      "description": "The string must match a decimal number with the following constraints: it starts with an optional minus sign; then there is at least one digit before the decimal point; if a decimal point appears, it must be followed by exactly two digits; the number must not have leading zeros unless it is zero; no other characters are allowed.",
      "regex": "/^-?(?:0|[1-9]\\d*)(?:\\.\\d{2})?$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "We need to automatically detect our test files in the repo so the CI can run them separately. A file counts as a test file if its name is made of one or more dot-separated parts (no slashes, only letters, digits, underscores, or hyphens in each part), followed by either .spec.ts or .test.js; the part right before that suffix must be exactly 'spec' or 'test', and the whole file name must be at least one character before it, so '.spec.ts' alone doesn't count.",
      "regex": "/^(?=.+\\.(?:spec\\.ts|test\\.js)$)[\\w-]+(?:\\.[\\w-]+)*(?:\\.spec\\.ts|\\.test\\.js)$/"
    },
    {
      "slot": 2,
      "description": "Match a Windows absolute path that starts with a drive letter followed by a colon and a backslash. After that, allow any sequence of backslash-separated components where each component contains at least one character and no backslashes or colons.",
      "regex": "/^[A-Za-z]:\\\\[^\\\\:]+(?:\\\\[^\\\\:]+)*$/"
    },
    {
      "slot": 3,
      "description": "Identify a test file name (no directory separators). The name must satisfy all of the following:\n- It is composed of one or more segments separated by single dots.\n- Each segment consists of ASCII letters, digits, underscores, or hyphens.\n- The file name ends with either .spec.ts or .test.js.\n- The segment immediately before the final extension must be exactly 'spec' or 'test'.\n- At least one segment must appear before the spec/test segment, so bare '.spec.ts' and 'spec.ts' are invalid.",
      "regex": "/^(?=.+\\.(?:spec\\.ts|test\\.js)$)[\\w-]+(?:\\.[\\w-]+)*\\.(?:spec\\.ts|test\\.js)$/"
    },
    {
      "slot": 4,
      "description": "Match a hidden dotfile name: a string that starts with a dot, has at least one more character after it, no slashes, and no whitespace.",
      "regex": "/^\\.[^\\/\\s]+$/"
    },
    {
      "slot": 5,
      "description": "Match a hidden file name that begins with a dot and contains at least one more character; neither \".\" nor \"..\" are hidden files, the name cannot contain a slash, and the entire name (including the leading dot) must not be longer than 255 characters.",
      "regex": "/^(?!\\.{1,2}$)(?=[^\\/]{2,255}$)\\.[^\\/]+$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "We need to let users pick a handle for their public profile page. The handle can contain lowercase letters, digits, dots, underscores and hyphens, must be between 3 and 30 characters long, and cannot begin or end with a dot, underscore or hyphen.",
      "regex": "/^[a-z0-9](?:[a-z0-9._-]{1,28}[a-z0-9])?$/"
    },
    {
      "slot": 2,
      "description": "Validate a practical email address: a non-empty local part containing letters, digits, dots, underscores, percent signs, plus signs or hyphens, followed by an @, then a domain made of one or more labels of letters, digits and hyphens separated by dots, ending with a top-level domain of at least two letters. The local part cannot start or end with a dot, and dots cannot appear consecutively. The domain labels cannot start or end with a hyphen.",
      "regex": "/^[A-Za-z0-9_%+-]+(?:\\.[A-Za-z0-9_%+-]+)*@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+[A-Za-z]{2,}$/"
    },
    {
      "slot": 3,
      "description": "Validate an email address, but reject addresses from well-known free webmail providers. The format must be a practical email: local part with letters, digits, dots, underscores, percent signs, plus signs or hyphens (no leading/trailing dot, no consecutive dots), then @, then a domain of labels (letters, digits, hyphens; no leading/trailing hyphen) separated by dots, ending with a TLD of at least two letters. The domain part must not be gmail.com, yahoo.com, hotmail.com, outlook.com or aol.com, case-insensitively. Only format and domain exclusion are checked; existence or deliverability is not verified.",
      "regex": "/^(?![^@]+@(?:gmail|yahoo|hotmail|outlook|aol)\\.com$)[A-Za-z0-9_%+-]+(?:\\.[A-Za-z0-9_%+-]+)*@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+[A-Za-z]{2,}$/i"
    },
    {
      "slot": 4,
      "description": "We need to check the email field in our signup form. Accept standard email addresses: a local part with letters, digits, dots, underscores, plus signs or hyphens, an @, and a domain with at least one dot and a top-level domain of at least two letters.",
      "regex": "/^[A-Za-z0-9._+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$/"
    },
    {
      "slot": 5,
      "description": "Match an email address that belongs to the example.com domain. The local part may contain letters, digits, dots, underscores, plus signs or hyphens and must start with a letter or digit and end with a letter or digit. The domain must be exactly example.com, case-insensitive.",
      "regex": "/^[A-Za-z0-9](?:[A-Za-z0-9._+-]*[A-Za-z0-9])?@example\\.com$/i"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "eu vat number for ireland: 8 or 9 characters, first a digit, then either 6 or 7 digits, then a letter. case-insensitive for the final letter.",
      "regex": "/^\\d(?:\\d{6}[A-Z]|\\d{5}[A-Z]{2})$/i"
    },
    {
      "slot": 2,
      "description": "our checkout only accepts French postal codes for delivery addresses. A valid code is exactly five digits, and it cannot be all zeros.",
      "regex": "/^(?!00000)\\d{5}$/"
    },
    {
      "slot": 3,
      "description": "Customers in the UK enter their postcode at checkout. Accept the standard UK format: one or two letters for the area, one or two digits for the district, an optional letter, a space, a digit, then two letters for the sector.",
      "regex": "/^[A-Z]{1,2}\\d{1,2}[A-Z]? \\d[A-Z]{2}$/i"
    },
    {
      "slot": 4,
      "description": "For US shipping we need the ZIP code. It can be a five-digit ZIP, or a ZIP+4 with five digits, a hyphen, and four digits. Leading zeros are allowed.",
      "regex": "/^\\d{5}(?:-\\d{4})?$/"
    },
    {
      "slot": 5,
      "description": "French business registration numbers are either a SIREN (9 digits) or a SIRET (14 digits). We only check the format, not any key.",
      "regex": "/^\\d{9}(?:\\d{5})?$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "Validates a personal name. The string must consist of one or more letter characters from any Unicode script, optionally separated by single hyphen or apostrophe characters. Leading and trailing separators are not allowed, and consecutive separators are not allowed.",
      "regex": "/^\\p{L}+(?:[-'\\u2019]\\p{L}+)*$/u"
    },
    {
      "slot": 2,
      "description": "A name can contain letters from any language, and single hyphens or apostrophes between parts. It must start and end with a letter.",
      "regex": "/^\\p{L}+(?:[-'\\u2019]\\p{L}+)*$/u"
    },
    {
      "slot": 3,
      "description": "A numeric string that uses only decimal digit characters from any Unicode script. No separators, signs, or whitespace are allowed.",
      "regex": "/^\\p{Nd}+$/u"
    },
    {
      "slot": 4,
      "description": "For our multilingual registration form, we need to accept personal names written entirely in Greek characters, so that users entering their name in Greek script are validated correctly. The name may include spaces between words, but the entire string must consist only of Greek letters and spaces.",
      "regex": "/^[\\p{Script=Greek} ]+$/u"
    },
    {
      "slot": 5,
      "description": "Validates a display name for international users. The name must contain at least one letter from any Unicode script. It may additionally contain hyphens or apostrophes, but only as separators between letters, not at the start or end, and not consecutively.",
      "regex": "/^\\p{L}+(?:[-'\\u2019]\\p{L}+)*$/u"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "comma separated list of integers, no trailing comma",
      "regex": "/^-?\\d+(?:,-?\\d+)*$/"
    },
    {
      "slot": 2,
      "description": "A single CSV row consisting of exactly five fields separated by commas. Each field must be either empty or contain no commas and no double quotes.",
      "regex": "/^[^\",]*(?:,[^\",]*){4}$/"
    },
    {
      "slot": 3,
      "description": "We need to validate comma-separated numeric IDs for product batches; each ID must be a non-negative integer from 0 to 9999, and there must be at least one ID with no trailing comma.",
      "regex": "/^(?:\\d|[1-9]\\d|[1-9]\\d{2}|[1-9]\\d{3})(?:,(?:\\d|[1-9]\\d|[1-9]\\d{2}|[1-9]\\d{3}))*$/"
    },
    {
      "slot": 4,
      "description": "Standard Base64: length is a multiple of 4; characters are A-Z, a-z, 0-9, +, /; the string ends with zero, one, or two padding '=' characters. Unpadded Base64 is not allowed. When padding is present, it must be exactly one '=' after two data characters or exactly two '=' after one data character.",
      "regex": "/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/"
    },
    {
      "slot": 5,
      "description": "Match a comma-separated list of three to eight integers, each between -999 and 999 inclusive, with no trailing comma.",
      "regex": "/^-?(?:\\d|[1-9]\\d|[1-9]\\d{2})(?:,-?(?:\\d|[1-9]\\d|[1-9]\\d{2})){2,7}$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "Our build pipeline needs to identify test files. A valid test file name consists of a base name, a dot, one of the words spec or test, another dot, and then one of the extensions js, ts, jsx, or tsx. The base name must be at least one character long and cannot contain a slash or backslash. The words spec/test and the extension are case-sensitive and must be lowercase.",
      "regex": "/^[^/\\\\]+\\\\.(?:spec|test)\\\\.(?:js|ts|jsx|tsx)$/"
    },
    {
      "slot": 2,
      "description": "Match a Unix absolute path: it starts with a forward slash, and then consists of one or more path segments separated by single forward slashes. Each segment must be non-empty and may contain any character except a forward slash. The path must not end with a trailing slash.",
      "regex": "/^\\/(?:[^\\/]+\\/)*[^\\/]+$/"
    },
    {
      "slot": 3,
      "description": "Match a JavaScript test file name ending with .spec.js.",
      "regex": "/^.*\\.spec\\.js$/"
    },
    {
      "slot": 4,
      "description": "hidden dotfile name",
      "regex": "/^\\.[^\\/\\s]+$/"
    },
    {
      "slot": 5,
      "description": "A valid file name must:\n- not be empty\n- not contain any of the following characters: / \\ : * ? \" < > |\n- not contain control characters (ASCII 0-31)\n- not be . or ..\n- be at most 255 characters long",
      "regex": "/^(?!\\.{1,2}$)[^\\/\\\\:*?\"<>|\\x00-\\x1f]{1,255}$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "Our users need to create a passphrase for their account. It must be at least four words, where each word contains only lowercase letters (a-z). Words are separated by a single space. The entire passphrase must be at least 15 characters long. No other characters or punctuation are allowed.",
      "regex": "/^(?=.{15,}$)(?:[a-z]+ ){3,}[a-z]+$/"
    },
    {
      "slot": 2,
      "description": "Password must be 8 to 20 characters long and contain only letters (a-z, A-Z), digits (0-9), and the following special characters: !@#$%^&*. It must include at least one uppercase letter, one lowercase letter, and one digit. The password cannot contain the word 'password' in any case (i.e., 'password', 'PASSWORD', 'PassWord', etc.).",
      "regex": "/^(?!.*(?i:password))(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)[A-Za-z\\d!@#$%^&*]{8,20}$/"
    },
    {
      "slot": 3,
      "description": "Password must be between 8 and 64 characters long and consist of printable ASCII characters (codes 33 to 126). It must not contain any whitespace characters, and it must not have any character repeated three times consecutively (e.g., 'aaa', '111', '!!!' are forbidden).",
      "regex": "/^(?!.*(.)\\1{2})[!-~]{8,64}$/"
    },
    {
      "slot": 4,
      "description": "api key: starts with 'sk_live_', followed by exactly 32 characters from the set [a-zA-Z0-9]",
      "regex": "/^sk_live_[a-zA-Z0-9]{32}$/"
    },
    {
      "slot": 5,
      "description": "A PIN code is 4 to 6 digits and cannot consist of the same digit repeated (e.g., 1111 or 222222 are invalid).",
      "regex": "/^(?!([0-9])\\1+$)[0-9]{4,6}$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "http or https URL with optional www, domain with at least one dot, optional port, optional path/query/fragment. spaces not allowed.",
      "regex": "/^https?:\\/\\/(www\\.)?[a-zA-Z0-9-]+(\\.[a-zA-Z0-9-]+)+(\\/[^\\s]*)?$/"
    },
    {
      "slot": 2,
      "description": "Validate a CSS hex color code. It must start with a hash symbol. It can be either 3 digits, 4 digits, 6 digits, or 8 digits. Each digit must be a hexadecimal character (0-9, a-f, A-F). The entire string must be exactly the color code with no extra characters.",
      "regex": "/^#([0-9a-fA-F]{3}|[0-9a-fA-F]{4}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})$/"
    },
    {
      "slot": 3,
      "description": "Match a domain name that ends with the top-level domain .org. The domain must consist of one or more labels separated by dots. Each label may contain letters, digits, and hyphens, but must not start or end with a hyphen. The last label must be exactly 'org'. The whole string is the domain.",
      "regex": "/^(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?\\.)+org$/"
    },
    {
      "slot": 4,
