{
  "items": [
    {
      "slot": 1,
      "description": "Validate a semantic version string per the following rules:\n- Three dot-separated numeric components: major, minor, patch.\n- Each numeric component is either 0 or a positive integer with no leading zero (e.g., 0, 1, 10; not 01).\n- May be followed by an optional pre-release section: a hyphen then one or more dot-separated identifiers; each identifier consists of alphanumerics and hyphens, must be non-empty, and if it is purely numeric it must not have a leading zero.\n- May be followed by an optional build metadata section: a plus sign then one or more dot-separated identifiers; each identifier consists of alphanumerics and hyphens and must be non-empty.\n- If both pre-release and build metadata are present, the pre-release must come first, followed by the build metadata.\n- Only the format is checked; no checksums or calendar facts are validated.",
      "regex": "/^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-((?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\\.(?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\\+([0-9a-zA-Z-]+(?:\\.[0-9a-zA-Z-]+)*))?$/"
