    {
      "slot": 2,
      "description": "Match a version string that starts with three dot-separated numbers (major, minor, patch). It may optionally include a pre-release part after a hyphen, which is one or more dot-separated identifiers made of letters, digits, or hyphens. It may also optionally include build metadata after a plus sign, which is one or more dot-separated identifiers made of letters, digits, or hyphens. If both optional parts are present, the pre-release must come before the build metadata.",
      "regex": "/^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-((?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\\.(?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\\+([0-9a-zA-Z-]+(?:\\.[0-9a-zA-Z-]+)*))?$/"
    },
    {
      "slot": 3,
      "description": "Validate a calendar version string in the format YYYY.MM, where YYYY is a four-digit year (no leading zero restriction beyond being four digits overall) and MM is a two-digit month from 01 to 12. A leading zero is required for months 1 through 9. The string must contain exactly one dot separating the year and month, with no extra characters.",
      "regex": "/^\\d{4}\\.(0[1-9]|1[0-2])$/"
    },
    {
      "slot": 4,
      "description": "Validate a Python version specifier string according to the following grammar:\n- A specifier consists of one or more clauses separated by commas.\n- Each clause is an operator followed by a version.\n- Operators allowed: ==, !=, <=, >=, <, >, ~=, === (arbitrary equality). The operator ~= is the compatible release operator.\n- The version must be a valid PEP 440 version: an optional 'v' followed by a release segment of one or more dot-separated non-negative integers (each with no leading zero unless it is exactly \"0\"), and optionally followed by a pre-release, post-release, or dev-release segment, and optionally a local version label.\n- Pre-release segment: a, b, c, rc, alpha, beta, pre, preview followed by an optional integer (no leading zero unless 0).\n- Post-release segment: - followed by post or rev or r, followed by an optional integer, or just - followed by an integer.\n- Dev-release segment: .dev followed by an integer (no leading zero unless 0).\n- Local version label: + followed by one or more dot-separated identifiers, where each identifier is alphanumeric (letters, digits, hyphens, underscores, periods).\n- Whitespace is allowed around commas and operators, but not inside the version string.\n- Only the format is validated; version comparison semantics are not checked.",
      "regex": "/^\\s*(?:(?:===|==|!=|<=|>=|<|>|~=)\\s*v?\\d+(?:\\.\\d+)*(?:(?:[-_.]?(?:a|b|c|rc|alpha|beta|pre|preview)[-_.]?\\d*)|(?:[-_.]?(?:post|rev|r)[-_.]?\\d*)|(?:[-_.]?dev[-_.]?\\d*))*?(?:\\+[a-z0-9]+(?:[-_.][a-z0-9]+)*)?)\\s*(?:,\\s*(?:(?:===|==|!=|<=|>=|<|>|~=)\\s*v?\\d+(?:\\.\\d+)*(?:(?:[-_.]?(?:a|b|c|rc|alpha|beta|pre|preview)[-_.]?\\d*)|(?:[-_.]?(?:post|rev|r)[-_.]?\\d*)|(?:[-_.]?dev[-_.]?\\d*))*?(?:\\+[a-z0-9]+(?:[-_.][a-z0-9]+)*)?))*\\s*$/"
    },
    {
      "slot": 5,
      "description": "Match a Python version specifier, which is one or more version constraints separated by commas. Each constraint starts with one of the operators ==, !=, <=, >=, <, >, ~=, or ===, followed by optional spaces, then a version number. The version number may start with a 'v', then has dot-separated numbers, and may include pre-release tags like a1, b2, rc3, post-release tags like .post1, and dev tags like .dev0, and may end with a local version after a plus sign. Spaces around commas and after operators are allowed, but not inside the version number itself.",
      "regex": "/^\\s*(?:(?:===|==|!=|<=|>=|<|>|~=)\\s*v?\\d+(?:\\.\\d+)*(?:(?:[-_.]?(?:a|b|c|rc|alpha|beta|pre|preview)[-_.]?\\d*)|(?:[-_.]?(?:post|rev|r)[-_.]?\\d*)|(?:[-_.]?dev[-_.]?\\d*))*?(?:\\+[a-z0-9]+(?:[-_.][a-z0-9]+)*)?)\\s*(?:,\\s*(?:(?:===|==|!=|<=|>=|<|>|~=)\\s*v?\\d+(?:\\.\\d+)*(?:(?:[-_.]?(?:a|b|c|rc|alpha|beta|pre|preview)[-_.]?\\d*)|(?:[-_.]?(?:post|rev|r)[-_.]?\\d*)|(?:[-_.]?dev[-_.]?\\d*))*?(?:\\+[a-z0-9]+(?:[-_.][a-z0-9]+)*)?))*\\s*$/"
    }
  ]
}

