      "regex": "/^[0-9a-fA-F]{64}$/"
    },
    {
      "slot": 3,
      "description": "Our integration logs identifiers that are standard UUID version 4 values, and we need a field check that accepts only those that are version 4 and variant 1 (the variant used by RFC 4122). The canonical hyphenated grouping must be used.",
      "regex": "/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i"
    },
    {
      "slot": 4,
      "description": "- A ticket reference starts with an uppercase project key: two or more uppercase ASCII letters.\n- Then a hyphen.\n- Then a positive issue number: one or more digits, with no leading zero unless the number is exactly \"0\"? No, leading zeros are not allowed at all, so the first digit must be 1-9.\n- No other characters.",
      "regex": "/^[A-Z]{2,}-[1-9][0-9]*$/"
    },
    {
      "slot": 5,
      "description": "We generate sortable public IDs in our backend using ULID, and the client-side validation should accept only well-formed ULIDs: 26 characters in Crockford's base32 alphabet, excluding the letters I, L, O and U. The first character, which encodes the timestamp, must not be one of the three overflow letters: it can only be 0-7 to stay within the valid time range (but do not enforce any other time constraints). Case-insensitive input is acceptable.",
      "regex": "/^[0-7][0-9A-HJKMNP-TV-Z]{25}$/i"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "The string must consist of at most 10 words. Words are separated by one or more spaces. Each word must contain only letters (A-Z, a-z) and may end with an optional punctuation mark from the set . , ; : ! ?. Leading and trailing spaces are not allowed.",
      "regex": "/^\\s*\\b(?:[A-Za-z]+[.,;:!?]?\\s+){0,9}[A-Za-z]+[.,;:!?]?\\b\\s*$/"
    },
    {
      "slot": 2,
      "description": "Check that a user's post title follows our title case style: every word must start with a capital letter, and the rest of the letters in the word must be lowercase. Words may be separated by a single space. Punctuation is not allowed.",
      "regex": "/^([A-Z][a-z]*)( [A-Z][a-z]*)*$/"
    },
    {
      "slot": 3,
      "description": "Validate a sentence: it must start with an uppercase letter (A-Z), followed by any number of characters that are not periods, and must end with exactly one period. The period is the only allowed punctuation at the end, and no other periods may appear in the sentence.",
      "regex": "/^[A-Z][^.]*\\.$/"
    },
    {
      "slot": 4,
      "description": "whole word 'cat' in text",
      "regex": "/\\bcat\\b/"
    },
    {
      "slot": 5,
      "description": "We need to flag any user review that repeats the same word twice in a row (like 'very very good') for spam detection.",
      "regex": "/\\b(\\w+)\\s+\\1\\b/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "Our inventory system needs a quantity field that accepts only positive integers. The value must not have leading zeros unless it is exactly zero, but zero itself is not allowed because quantities must be at least one. So any string of digits representing a whole number greater than zero, without any leading zeros.",
      "regex": "/^(?:[1-9][0-9]*)$/"
    },
    {
      "slot": 2,
      "description": "The string must represent an integer from 0 to 255 inclusive, with no leading zeros unless the number is exactly 0. So it can be a single digit 0-9, or a two-digit number 10-99, or a three-digit number where the first digit is 1 and the last two digits are 00-99, or the first digit is 2 and the last two digits are 00-55. Leading zeros are not allowed.",
      "regex": "/^(?:[0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])$/"
    },
    {
      "slot": 3,
      "description": "In our financial application, the amount field must accept signed decimal numbers. An optional plus or minus sign is allowed at the beginning. The integer part must be one or more digits without leading zeros (unless the number is zero). An optional fractional part may follow, consisting of a decimal point and one or more digits. So valid examples include -0.5, +123, 0.00, but not 00.1 or 1.",
      "regex": "/^[+-]?(?:0|[1-9][0-9]*)(?:\\.[0-9]+)?$/"
    },
    {
      "slot": 4,
      "description": "The system requires an integer between 1 and 100 inclusive. No leading zeros are allowed except for the number 0, but 0 is not valid here. So valid values are 1 through 99 as one or two digits without leading zeros, and 100 exactly.",
      "regex": "/^(?:[1-9]|[1-9][0-9]|100)$/"
    },
    {
      "slot": 5,
      "description": "For a game scoring system, we need to accept only even numbers as the final score. The number must be a non-negative integer, written without leading zeros. So any string of digits that represents an even number, including 0, 2, 10, 100, but not 1, 3, or 01.",
      "regex": "/^(?:0|[1-9][0-9]*[02468])$/"
    }
  ]
}

{
