      "regex": "/^(?!\\1{3,5}$)(\\d){4,6}$/"
    },
    {
      "slot": 3,
      "description": "password without whitespace and without the same character three times in a row",
      "regex": "/^(?!.*(.)\\1\\1)[^\\s]+$/"
    },
    {
      "slot": 4,
      "description": "Passphrase rules: It must consist of at least four words. Words are separated by a single space. Each word must contain only letters (a-z, A-Z) and be at least one character long. No leading or trailing spaces are allowed. The entire passphrase has no length limit beyond what the words provide. Case is not restricted.",
      "regex": "/^(?:[A-Za-z]+ ){3,}[A-Za-z]+$/"
    },
    {
      "slot": 5,
      "description": "password with min 8 chars, at least one uppercase, one lowercase, one digit",
      "regex": "/^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d).{8,}$/"
    }
  ]
}

