      "regex": "/^(?=[^\\n]*(?:\\n[^\\n]+)*\\n\\n)(?![\\s\\S]*\\n\\n$)[^\\n]+(?:\\n[^\\n]+)*\\n\\n(?:\\n)*[^\\n]+(?:\\n[^\\n]+)*$/"
