      "regex": "/^\\s*(?:(?:===|==|!=|<=|>=|~=|<|>)\\s*)?\\d+(?:\\.\\d+)*(?:(?:a|b|rc)\\d+)?(?:\\s*,\\s*(?:(?:===|==|!=|<=|>=|~=|<|>)\\s*)?\\d+(?:\\.\\d+)*(?:(?:a|b|rc)\\d+)?)*\\s*$/i"
