{
  "items": [
    {
      "slot": 1,
      "description": "Write a regex that matches a weight written as a number followed by either kg or g. The number may be an integer or have a decimal part, using a dot as separator. No spaces are allowed between the number and the unit. The unit is case-insensitive.",
      "regex": "/^\\d+(?:\\.\\d+)?(?:kg|g)$/i"
    },
    {
      "slot": 2,
      "description": "A file size string must consist of a positive integer (no leading zeros unless it is exactly zero), optionally followed by a decimal part with exactly one or two digits, then an optional single space, and finally one of the units B, KB, MB, or GB. The unit is case-insensitive. The number must not start with a dot. Examples of valid: \"0 B\", \"1.5 KB\", \"10MB\". Invalid: \"01 KB\", \".5 MB\", \"1.2.3 GB\".",
      "regex": "/^(?:0|[1-9]\\d*)(?:\\.\\d{1,2})? ?(?:B|KB|MB|GB)$/i"
    },
    {
      "slot": 3,
      "description": "A weight measurement string must start with a number (integer or decimal with a dot) that is greater than zero and less than 1000, followed by an optional space, and then either \"kg\" or \"g\" (case-insensitive). The number must not have leading zeros, and if it has a decimal part, it must have at least one digit after the dot. The number must not be exactly 1000 or more. Valid: \"0.5 kg\", \"999 g\", \"1.23kg\". Invalid: \"0 kg\", \"1000 g\", \"01.5 kg\", \".5 g\".",
      "regex": "/^(?:(?:[1-9]\\d{0,2})(?:\\.\\d+)?|0\\.\\d+)(?: ?)(?:kg|g)$/i"
    },
    {
      "slot": 4,
      "description": "latitude between -90 and 90",
      "regex": "/^-?(?:90(?:\\.0+)?|[1-8]?\\d(?:\\.\\d+)?)$/"
    },
    {
      "slot": 5,
      "description": "longitude in decimal degrees",
      "regex": "/^-?(?:180(?:\\.0+)?|(?:1[0-7]\\d|[1-9]?\\d)(?:\\.\\d+)?)$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "css length with unit: number plus one of px, em, rem, %, vh, vw; number may be signed and decimal; no spaces",
