      "regex": "/^<p(?:>| (?:[A-Za-z][A-Za-z0-9_-]*(?:=\"[^\"]*\")?)(?: [A-Za-z][A-Za-z0-9_-]*(?:=\"[^\"]*\")?)*>)$/"
