{
  "items": [
    {
      "slot": 1,
      "description": "We need to validate a string input that represents an ISO 8601 duration. The format must start with 'P', followed by one or more components in any order: years, months, days, hours, minutes, seconds. Each component is a positive integer (no leading zeros unless the number is zero) followed by a designator: 'Y', 'M', 'D', 'H', 'S'. Note: 'M' is used for both months and minutes, but in ISO 8601, the context distinguishes: if 'T' is present, 'M' after 'T' means minutes; before 'T', 'M' means months. However, for this validation, we just need to ensure the overall structure: an optional date part (years, months, days) and an optional time part preceded by 'T' (hours, minutes, seconds), with at least one component present. No negative numbers or fractions allowed. Only the format is checked.",
      "regex": "/^P(?:\\d+Y)?(?:\\d+M)?(?:\\d+D)?(?:T(?:\\d+H)?(?:\\d+M)?(?:\\d+S)?)?$/"
    },
    {
      "slot": 2,
      "description": "Match a valid ISO 8601 duration string. It starts with P, then may have years, months, days, and optionally a T followed by hours, minutes, and seconds. At least one component must be present.",
      "regex": "/^P(?:\\d+Y)?(?:\\d+M)?(?:\\d+D)?(?:T(?:\\d+H)?(?:\\d+M)?(?:\\d+S)?)?$/"
