    {
      "slot": 3,
      "description": "Match a file name that starts with a date in YYYY-MM-DD format, followed by an underscore and a description. The description may contain letters, digits, hyphens, and underscores, but no spaces or path separators. The date must be a valid calendar date (with correct month lengths and leap years).",
      "regex": "/^(?:(?:(?:19|20)\\d{2})-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|02-(?:0[1-9]|1\\d|2[0-8]))|(?:(?:19|20)(?:0[48]|[2468][048]|[13579][26])|(?:[02468][048]|[13579][26])00)-02-29)_[A-Za-z0-9_-]+$/"
