{
  "items": [
    {
      "slot": 1,
      "description": "We need to validate the version field in our deployment configuration. It should be a calendar version in the format YYYY.MM, where the year is any four-digit number and the month is exactly two digits from 01 to 12.",
      "regex": "/^\\d{4}\\.(0[1-9]|1[0-2])$/"
    },
    {
      "slot": 2,
      "description": "A valid semantic version string consists of three numeric components separated by dots: major, minor, and patch, each being a non-negative integer without leading zeros. It may be followed by an optional pre-release version and an optional build metadata. The pre-release version starts with a hyphen and consists of dot-separated identifiers, each identifier being either a numeric identifier without leading zeros or an alphanumeric identifier containing only ASCII alphanumeric characters and hyphens. The build metadata starts with a plus sign and consists of dot-separated identifiers, each identifier being any combination of ASCII alphanumeric characters and hyphens. The pre-release and build metadata must not be empty.",
      "regex": "/^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-((?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\\.(?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\\+([0-9a-zA-Z-]+(?:\\.[0-9a-zA-Z-]+)*))?$/"
    },
    {
      "slot": 3,
      "description": "Match a semantic version number optionally followed by a pre-release identifier and build metadata. The core version is three dot-separated numbers without leading zeros. The pre-release part starts with a hyphen and consists of dot-separated identifiers of alphanumerics or hyphens, and the build metadata starts with a plus sign and consists of dot-separated alphanumeric or hyphen identifiers.",
      "regex": "/^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-((?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\\.(?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\\+([0-9a-zA-Z-]+(?:\\.[0-9a-zA-Z-]+)*))?$/"
    },
    {
      "slot": 4,
      "description": "A valid git tag for releases starts with the letter 'v' (lowercase), followed by a version number that can be either in the form major.minor or major.minor.patch, where each component is a non-negative integer without leading zeros.",
      "regex": "/^v(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:\\.(0|[1-9]\\d*))?$/"
    },
    {
      "slot": 5,
      "description": "A valid npm version range can be a single version number optionally preceded by a caret or tilde, where a version number is major.minor.patch with each part being a non-negative integer without leading zeros. The caret allows changes that do not modify the left-most non-zero digit, and the tilde allows patch-level changes if a minor version is specified. The range may also include a space-separated list of such version constraints (e.g., for compound ranges), but each individual constraint must follow the above format.",
      "regex": "/^(?:\\^|~)?(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?: (?:\\^|~)?(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*))*$/"
    }
  ]
}

