{
  "items": [
    {
      "slot": 1,
      "description": "We need to validate the hostname field in our infrastructure provisioning form. The hostname must follow RFC 1123: the total length must not exceed 253 characters; it consists of dot-separated labels; each label may contain only letters, digits, and hyphens; each label must start and end with a letter or digit, cannot be empty, and cannot exceed 63 characters. The hostname must not end with a trailing dot.",
      "regex": "/^(?=.{1,253}$)(?!-)[a-zA-Z0-9-]{1,63}(?<!-)\\.(?!-)[a-zA-Z0-9-]{1,63}(?<!-)(?:\\.(?!-)[a-zA-Z0-9-]{1,63}(?<!-))*$/"
    },
    {
      "slot": 2,
      "description": "A MAC address consists of six pairs of hexadecimal digits. The pairs may be separated consistently by either colons, hyphens, or no separator at all. Mixed separators are not allowed.",
      "regex": "/^([0-9A-Fa-f]{2}(:|-)?){5}[0-9A-Fa-f]{2}$/"
    },
    {
      "slot": 3,
      "description": "Match a MAC address. It must be six pairs of hexadecimal digits, with the same separator between all pairs. The separator can be a colon or a dash. Uppercase or lowercase letters are allowed. No separator is also acceptable.",
      "regex": "/^([0-9A-Fa-f]{2}([:-]?)){5}[0-9A-Fa-f]{2}$/"
    },
    {
      "slot": 4,
      "description": "mac address with consistent separator",
      "regex": "/^([0-9A-Fa-f]{2}([:-]?)){5}[0-9A-Fa-f]{2}$/"
    },
    {
      "slot": 5,
      "description": "ipv4 cidr block",
      "regex": "/^(?:(?:25[0-5]|2[0-4][0-9]|1[0-9][0-9]|[1-9]?[0-9])\\.){3}(?:25[0-5]|2[0-4][0-9]|1[0-9][0-9]|[1-9]?[0-9])(?:\\/(?:3[0-2]|[12]?[0-9]))$/"
    }
  ]
}

{
  "items": [
