{
  "items": [
    {
      "slot": 1,
      "description": "Validate a semantic version string. Rules:\n- Starts with three dot-separated numeric identifiers: major, minor, patch.\n- Each numeric identifier is one or more digits and must not have leading zeros.\n- Optionally followed by a pre-release identifier: a hyphen and one or more dot-separated alphanumeric identifiers. Each alphanumeric identifier contains only ASCII letters, digits, and hyphens, and must not be empty.\n- Optionally followed by build metadata: a plus sign and one or more dot-separated alphanumeric identifiers. Each alphanumeric identifier contains only ASCII letters, digits, and hyphens, and must not be empty.\n- No other characters are allowed.",
      "regex": "/^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-((?:[0-9A-Za-z-]+)(?:\\.[0-9A-Za-z-]+)*))?(?:\\+((?:[0-9A-Za-z-]+)(?:\\.[0-9A-Za-z-]+)*))?$/"
    },
    {
      "slot": 2,
      "description": "Validate an npm version range that starts with either a caret (^) or a tilde (~). Rules:\n- The range must begin with exactly one of ^ or ~.\n- After that, a valid semantic version: three dot-separated numeric identifiers without leading zeros, optionally followed by a pre-release identifier (a hyphen and one or more dot-separated alphanumeric identifiers), and optionally followed by build metadata (a plus sign and one or more dot-separated alphanumeric identifiers).\n- No other characters are allowed.",
      "regex": "/^[~^](0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-((?:[0-9A-Za-z-]+)(?:\\.[0-9A-Za-z-]+)*))?(?:\\+((?:[0-9A-Za-z-]+)(?:\\.[0-9A-Za-z-]+)*))?$/"
    },
    {
      "slot": 3,
      "description": "Match a semantic version with optional pre-release and build metadata. It must have three dot-separated numeric identifiers with no leading zeros. A pre-release is a hyphen followed by dot-separated identifiers made only of letters, digits, and hyphens. A build metadata is a plus sign followed by dot-separated identifiers made only of letters, digits, and hyphens. Either or both may be absent, but if both are present, the pre-release comes before the build metadata.",
      "regex": "/^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-((?:[0-9A-Za-z-]+)(?:\\.[0-9A-Za-z-]+)*))?(?:\\+((?:[0-9A-Za-z-]+)(?:\\.[0-9A-Za-z-]+)*))?$/"
    },
    {
      "slot": 4,
      "description": "We use git tags to mark releases. The tag format we use starts with a lowercase v followed by either two dot-separated numbers or three dot-separated numbers. Each number is one or more digits with no leading zeros. No other characters are allowed.",
      "regex": "/^v(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:\\.(0|[1-9]\\d*))?$/"
    },
    {
      "slot": 5,
      "description": "Match a semantic version that has three dot-separated numeric identifiers (no leading zeros), optionally followed by a pre-release identifier and optionally by build metadata. A pre-release identifier is a hyphen followed by dot-separated groups of ASCII letters, digits, and hyphens. Build metadata is a plus sign followed by dot-separated groups of ASCII letters, digits, and hyphens. Both optional parts may appear, but the pre-release must come before the build metadata.",
      "regex": "/^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-((?:[0-9A-Za-z-]+)(?:\\.[0-9A-Za-z-]+)*))?(?:\\+((?:[0-9A-Za-z-]+)(?:\\.[0-9A-Za-z-]+)*))?$/"
    }
  ]
}

{
