{
  "items": [
    {
      "slot": 1,
      "description": "A string that is wrapped in matching quotes. It must start with either a single quote, a double quote, or a backtick, and end with the same type of quote. The content inside may be any characters except newlines, and the opening quote must not appear unescaped inside if it is the same as the delimiter. For simplicity, assume no escaping is allowed; the inner content cannot contain the delimiter character that matches the opening quote.",
      "regex": "/^(?:'[^'\\n]*'|\"[^\"\\n]*\"|`[^`\\n]*`)$/"
    },
    {
      "slot": 2,
      "description": "We need to check a user-entered short title that must be no more than 8 words. Words are separated by single spaces, and each word consists of letters (a-z, A-Z) and may include an apostrophe.",
      "regex": "/^[A-Za-z']+(?: [A-Za-z']+){0,7}$/"
    },
    {
      "slot": 3,
      "description": "The text must contain at least one word that appears twice consecutively (e.g., a repeated word). Words are sequences of letters, case-insensitive.",
      "regex": "/\\b(\\w+)\\s+\\1\\b/i"
    },
    {
      "slot": 4,
      "description": "Determine whether the text contains the whole word 'cat' as a separate word, not as part of another word like 'cater' or 'scatter'. The match should be case-sensitive.",
      "regex": "/(?<!\\w)cat(?!\\w)/"
    },
    {
      "slot": 5,
      "description": "Determine whether the text contains the whole word 'apple' as a separate word, not as part of another word like 'pineapple' or 'apples'. The match should be case-insensitive.",
      "regex": "/(?<!\\w)apple(?!\\w)/i"
    }
  ]
}

{
