{
  "items": [
    {
      "slot": 1,
      "description": "Match a single CSV line containing exactly three fields separated by commas. Each field may contain letters (uppercase or lowercase), digits, spaces, and hyphens, but no commas, and the line must not begin or end with a comma.",
      "regex": "/^[A-Za-z0-9 -]+,[A-Za-z0-9 -]+,[A-Za-z0-9 -]+$/"
    },
    {
      "slot": 2,
      "description": "Match a string that represents an XML-like element consisting of an opening tag and a matching closing tag, with optional content in between. The tag name must start with a letter and may contain letters, digits, hyphens, underscores, or periods. There may be any number of characters (including newlines) between the tags, but the closing tag name must exactly match the opening tag name (case-sensitive). No other elements or text are allowed outside the tags.",
      "regex": "/^<([A-Za-z][\\w.-]*)>[\\s\\S]*<\\/\\1>$/"
    },
    {
      "slot": 3,
      "description": "Match a single CSV line containing exactly two fields separated by a semicolon. Each field must consist only of letters (uppercase or lowercase), digits, spaces, or hyphens, and neither field may be empty. The line must not start or end with a semicolon.",
      "regex": "/^[A-Za-z0-9 -]+;[A-Za-z0-9 -]+$/"
    },
    {
      "slot": 4,
      "description": "Match a valid JSON array of numbers. The array must start with '[' and end with ']'. Inside, there must be zero or more numbers separated by commas. Each number may be an integer or a decimal, may start with an optional minus sign, and may have an optional fractional part (a dot followed by at least one digit). Leading zeros are not allowed unless the number is exactly 0. Whitespace (spaces, tabs, newlines) is allowed before and after the brackets, around commas, and around numbers. The array must not contain any other characters.",
      "regex": "/^\\s*\\[\\s*(?:-?(?:0|[1-9]\\d*)(?:\\.\\d+)?)?(?:\\s*,\\s*-?(?:0|[1-9]\\d*)(?:\\.\\d+)?)*\\s*\\]\\s*$/"
    },
    {
      "slot": 5,
      "description": "Match a string that has the shape of a JWT (JSON Web Token): three parts separated by dots. Each part must be a non-empty Base64URL string, which consists of letters (A-Z, a-z), digits (0-9), hyphens (-), and underscores (_). The string must contain exactly two dots, separating the three parts.",
      "regex": "/^[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+$/"
    }
  ]
}

{
