      "slot": 1,
      "description": "We need to verify that the path entered by users is a valid URL path without any query parameters. A valid path starts with a slash, may be followed by one or more segments separated by slashes, and each segment can contain letters, digits, hyphens, underscores, dots, or percent-encoded characters (percent followed by two hexadecimal digits). No query string (starting with ?) or fragment (starting with #) is allowed. The path must not contain spaces or other characters outside this set.",
      "regex": "/^\\/(?:[A-Za-z0-9._~%-]+(?:\\/[A-Za-z0-9._~%-]+)*)?$/"
    },
    {
      "slot": 2,
      "description": "html opening tag for a div element",
      "regex": "/^<div(?:\\s+[a-zA-Z_:][-a-zA-Z0-9_:.]*(?:\\s*=\\s*(?:\"[^\"]*\"|'[^']*'|[^\\s\"'=<>`]+))?)*\\s*>$/"
    },
    {
      "slot": 3,
      "description": "relative URL path starting with a slash",
      "regex": "/^\\/(?:[\\w.~!$&'()*+,;=:@-]|%[0-9A-Fa-f]{2})*(?:\\/(?:[\\w.~!$&'()*+,;=:@-]|%[0-9A-Fa-f]{2})*)*$/"
    },
    {
      "slot": 4,
      "description": "Our design system requires that all CSS length values entered in the theme editor are valid. A valid CSS length consists of a number (integer or decimal, optionally with a leading minus sign) followed immediately by a unit. The allowed units are px, em, rem, vh, vw, and the percent sign. The number must have at least one digit before the decimal point if a decimal is present, and if a decimal point is used, it must be followed by at least one digit. No spaces are allowed between the number and the unit, and the entire string must be exactly this number+unit without any extra characters. For example, values like '10px', '-0.5em', '2.5rem', '100%' are valid, but '10 px', 'px', '10', '10.px' are not.",
      "regex": "/^-?\\d+(?:\\.\\d+)?(?:px|em|rem|vh|vw|%)$/"
    },
    {
      "slot": 5,
      "description": "A CSS hex color value must be either:\n- a hash symbol followed by exactly 3 hexadecimal digits (0-9, a-f, A-F), or\n- a hash symbol followed by exactly 6 hexadecimal digits (0-9, a-f, A-F).\nNo other characters are allowed. The entire string must match this pattern.",
      "regex": "/^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/"
    }
  ]
}

