      "regex": "/^(10\\.(?:\\d{1,2}|1\\d{2}|2[0-4]\\d|25[0-5])\\.(?:\\d{1,2}|1\\d{2}|2[0-4]\\d|25[0-5])\\.(?:\\d{1,2}|1\\d{2}|2[0-4]\\d|25[0-5]))|(172\\.(?:1[6-9]|2\\d|3[0-1])\\.(?:\\d{1,2}|1\\d{2}|2[0-4]\\d|25[0-5])\\.(?:\\d{1,2}|1\\d{2}|2[0-4]\\d|25[0-5]))|(192\\.168\\.(?:\\d{1,2}|1\\d{2}|2[0-4]\\d|25[0-5])\\.(?:\\d{1,2}|1\\d{2}|2[0-4]\\d|25[0-5]))$/"
    },
    {
      "slot": 2,
      "description": "Match an IPv4 CIDR block. It consists of four dot-separated decimal octets, each between 0 and 255, followed by a slash and a prefix length between 0 and 32.",
      "regex": "/^(?:(?:25[0-5]|2[0-4]\\d|1\\d{2}|[1-9]?\\d)\\.){3}(?:25[0-5]|2[0-4]\\d|1\\d{2}|[1-9]?\\d)\\/(?:3[0-2]|[12]?\\d)$/"
    },
    {
      "slot": 3,
      "description": "Accept an IPv4 CIDR block according to these rules:\n- Exactly four decimal octets separated by dots.\n- Each octet must be a whole number from 0 to 255, without leading zeros (e.g., '0' is allowed, '01' is not).\n- After the fourth octet, a slash ('/') and a prefix length from 0 to 32, inclusive. Leading zeros in the prefix length are not allowed.",
      "regex": "/^(?:(?:25[0-5]|2[0-4]\\d|1\\d{2}|[1-9]\\d|0)\\.){3}(?:25[0-5]|2[0-4]\\d|1\\d{2}|[1-9]\\d|0)\\/(?:3[0-2]|[12]?\\d|0)$/"
    },
    {
      "slot": 4,
      "description": "Our server configuration tool requires a port number. The port must be an integer between 1 and 65535, inclusive. No leading zeros unless the number is exactly zero, but zero is not allowed.",
      "regex": "/^(?:6553[0-5]|655[0-2]\\d|65[0-4]\\d{2}|6[0-4]\\d{3}|[1-5]\\d{4}|[1-9]\\d{0,3})$/"
    },
    {
      "slot": 5,
      "description": "Validate a private IPv4 address according to RFC 1918. The address must be a dotted-decimal string with four octets, each 0–255, and must fall into one of these ranges:\n- 10.0.0.0 to 10.255.255.255\n- 172.16.0.0 to 172.31.255.255\n- 192.168.0.0 to 192.168.255.255",
      "regex": "/^(?:10\\.(?:25[0-5]|2[0-4]\\d|1\\d{2}|[1-9]?\\d)\\.(?:25[0-5]|2[0-4]\\d|1\\d{2}|[1-9]?\\d)\\.(?:25[0-5]|2[0-4]\\d|1\\d{2}|[1-9]?\\d)|172\\.(?:1[6-9]|2\\d|3[01])\\.(?:25[0-5]|2[0-4]\\d|1\\d{2}|[1-9]?\\d)\\.(?:25[0-5]|2[0-4]\\d|1\\d{2}|[1-9]?\\d)|192\\.168\\.(?:25[0-5]|2[0-4]\\d|1\\d{2}|[1-9]?\\d)\\.(?:25[0-5]|2[0-4]\\d|1\\d{2}|[1-9]?\\d))$/"
    }
  ]
}

{
