      "description": "Match a CSS class name written in BEM style. It starts with a block name of one or more lowercase letters, may be followed by an element part that begins with two underscores and contains one or more lowercase letters, and may be followed by a modifier part that begins with two hyphens and contains one or more lowercase letters.",
      "regex": "/^[a-z]+(?:_[a-z]+)?(?:--[a-z]+)?$/"
    },
