{
  "items": [
    {
      "description": "We need to validate version strings in our release notes to ensure they follow semantic versioning, including optional pre-release and build metadata, so that the changelog parser can group releases correctly.",
      "regex": "/^\\d+\\.\\d+\\.\\d+(?:-[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?(?:\\+[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?$/"
    },
    {
      "description": "A valid npm version range with a caret or tilde must start with either ^ or ~, followed by a valid semantic version (major.minor.patch), where each part is a non-negative integer without leading zeros except for zero itself. The range may optionally include pre-release identifiers and build metadata as defined by semver. The entire string must match exactly; no leading or trailing whitespace or other characters are allowed.",
      "regex": "/^[\\^~](?:0|[1-9]\\d*)\\.(?:0|[1-9]\\d*)\\.(?:0|[1-9]\\d*)(?:-[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?(?:\\+[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?$/"
    },
    {
      "description": "A valid semantic version consists of three non-negative integers separated by dots, where each integer has no leading zeros unless it is zero. The first two integers are the major and minor versions. The third integer is the patch version, and it may optionally be followed by a hyphen and a pre-release identifier. The pre-release identifier must consist of alphanumeric characters and hyphens, with each dot-separated part non-empty. The entire string must match exactly; no leading or trailing whitespace or other characters are allowed.",
      "regex": "/^(?:0|[1-9]\\d*)\\.(?:0|[1-9]\\d*)\\.(?:0|[1-9]\\d*)(?:-[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?$/"
    },
    {
      "description": "cal version year month 2024.06",
      "regex": "/^\\d{4}\\.(0[1-9]|1[0-2])$/"
    },
    {
      "description": "A valid git tag consists of the character 'v' followed by a version number in the format major.minor or major.minor.patch. Major and minor are non-negative integers without leading zeros unless the number is zero. Patch, if present, must also be a non-negative integer without leading zeros unless zero. The entire string must match exactly; no leading or trailing whitespace or other characters are allowed.",
      "regex": "/^v(?:0|[1-9]\\d*)\\.(?:0|[1-9]\\d*)(?:\\.(?:0|[1-9]\\d*))?$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "A simplified five-field cron expression. The five fields are separated by single spaces: minute (0-59), hour (0-23), day of month (1-31), month (1-12), day of week (0-6, where 0 is Sunday). Each field may be a single number, a comma-separated list of numbers without spaces, or a range written as two numbers separated by a hyphen (inclusive). Steps and names are not allowed.",
      "regex": "/^(?:\\d|[1-5]\\d)(?:,(?:\\d|[1-5]\\d))* (?:\\d|1\\d|2[0-3])(?:,(?:\\d|1\\d|2[0-3]))* (?:[1-9]|[12]\\d|3[01])(?:,(?:[1-9]|[12]\\d|3[01]))* (?:[1-9]|1[0-2])(?:,(?:[1-9]|1[0-2]))* [0-6](?:,[0-6])*$/"
    },
    {
      "slot": 2,
      "description": "Our scheduling UI accepts a simplified five-field cron expression. Each field separated by one space: minute 0-59, hour 0-23, day of month 1-31, month 1-12, day of week 0-6 with 0 as Sunday. A field can be a single number, a comma-separated list of numbers, or a numeric range (inclusive) written with a hyphen; lists and ranges may be mixed inside a comma-separated list. No step values, no names, no extra spaces.",
      "regex": "/^(?:(?:\\d|[1-5]\\d)|(?:\\d|[1-5]\\d)-(?:\\d|[1-5]\\d))(?:,(?:(?:\\d|[1-5]\\d)|(?:\\d|[1-5]\\d)-(?:\\d|[1-5]\\d)))* (?:(?:\\d|1\\d|2[0-3])|(?:\\d|1\\d|2[0-3])-(?:\\d|1\\d|2[0-3]))(?:,(?:(?:\\d|1\\d|2[0-3])|(?:\\d|1\\d|2[0-3])-(?:\\d|1\\d|2[0-3])))* (?:(?:[1-9]|[12]\\d|3[01])|(?:[1-9]|[12]\\d|3[01])-(?:[1-9]|[12]\\d|3[01]))(?:,(?:(?:[1-9]|[12]\\d|3[01])|(?:[1-9]|[12]\\d|3[01])-(?:[1-9]|[12]\\d|3[01])))* (?:(?:[1-9]|1[0-2])|(?:[1-9]|1[0-2])-(?:[1-9]|1[0-2]))(?:,(?:(?:[1-9]|1[0-2])|(?:[1-9]|1[0-2])-(?:[1-9]|1[0-2])))* (?:[0-6]|[0-6]-[0-6])(?:,(?:[0-6]|[0-6]-[0-6]))*$/"
    },
    {
      "slot": 3,
      "description": "A semantic PR title starts with a type from the list feat, fix, docs, style, refactor, perf, test, chore, ci, or build, followed by an optional scope in parentheses containing one or more lowercase letters, digits, or hyphens, then a colon and a single space. After that comes a non-empty description, and the title must contain a ticket key of the form uppercase letters, a hyphen, and digits, surrounded by word boundaries.",
      "regex": "/^(?:feat|fix|docs|style|refactor|perf|test|chore|ci|build)(?:\\([a-z0-9-]+\\))?: .+\\b[A-Z]+-\\d+\\b.+$/"
    },
    {
      "slot": 4,
      "description": "Validate a simplified five-field cron expression. Fields are separated by single spaces: minute 0-59, hour 0-23, day of month 1-31, month 1-12, day of week 0-6 (Sunday is 0). Each field is either a single number, a comma-separated list of numbers, or a range of two numbers separated by a hyphen. No step values or names.",
      "regex": "/^(?:\\d|[1-5]\\d)(?:,(?:\\d|[1-5]\\d))* (?:\\d|1\\d|2[0-3])(?:,(?:\\d|1\\d|2[0-3]))* (?:[1-9]|[12]\\d|3[01])(?:,(?:[1-9]|[12]\\d|3[01]))* (?:[1-9]|1[0-2])(?:,(?:[1-9]|1[0-2]))* [0-6](?:,[0-6])*$/"
    },
    {
      "slot": 5,
      "description": "Git branch names in our repo follow a convention that starts with a type (feature, bugfix, hotfix, or release), then a forward slash, then a ticket key (uppercase letters followed by a hyphen and digits), then a hyphen, and finally a short slug of lowercase words separated by hyphens. The slug must not be empty and must not contain uppercase letters or characters other than a-z, 0-9, and hyphens.",
      "regex": "/^(?:feature|bugfix|hotfix|release)\\/[A-Z]+-\\d+-[a-z0-9]+(?:-[a-z0-9]+)*$/"
    }
  ]
}

