{
  "items": [
    {
      "slot": 1,
      "description": "Match a signed decimal number: an optional sign, then one or more digits, optionally followed by a decimal point and one or more digits.",
      "regex": "/^[+-]?\\d+(\\.\\d+)?$/"
    },
    {
      "slot": 2,
      "description": "Match a signed decimal number that allows an optional leading plus or minus, digits before the decimal point, and if a decimal point is present, exactly two digits after it.",
      "regex": "/^[+-]?\\d+(\\.\\d{2})?$/"
    },
    {
      "slot": 3,
      "description": "We need to validate scientific notation numbers entered by users, like in our calculator app. The format should be a number (with optional decimal part) followed by 'e' or 'E' and an optional sign and one or more digits.",
      "regex": "/^[+-]?\\d+(\\.\\d+)?[eE][+-]?\\d+$/"
    },
    {
      "slot": 4,
      "description": "Match a number with thousands separated by commas: groups of three digits after the first group, with an optional sign.",
      "regex": "/^[+-]?\\d{1,3}(,\\d{3})*$/"
    },
    {
      "slot": 5,
      "description": "We need to accept scientific notation numbers that may include a leading sign, a significant with optional decimal point, and an exponent part. The significant must have at least one digit before the decimal point if a decimal point is present, and at least one digit after if present. If no decimal point, at least one digit. The exponent is 'e' or 'E' followed by an optional sign and one or more digits. No leading or trailing spaces or commas allowed.",
      "regex": "/^[+-]?(\\d+(\\.\\d*)?|\\.\\d+)[eE][+-]?\\d+$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "A valid amount in Japanese yen must satisfy the following rules:\n- The amount is written as an integer number of yen.\n- No decimal part or decimal point is allowed.\n- A thousands separator (comma) may be used to group digits in groups of three, but it is optional.\n- If a comma is used, it must appear between every group of three digits from the right, and the leftmost group may have one to three digits.\n- The amount must contain at least one digit.\n- Leading zeros are allowed.\n- No currency symbol, spaces, or other characters are permitted.\n- The entire string must match exactly (no extra characters before or after).",
      "regex": "/^(?:0|[1-9]\\d{0,2}(?:,\\d{3})*|[1-9]\\d*)$/"
    },
