{
  "items": [
    {
      "slot": 1,
      "description": "Our monitoring tool needs to spot log lines that report an operation duration of more than one second. The line must contain the phrase 'duration=' immediately followed by a number and then 'ms'. The number is a positive integer (no plus sign, no leading zeros unless it's just '0') and must be greater than 1000. The rest of the line can be anything. Only lines where the duration is strictly above one second should be flagged.",
      "regex": "/\\bduration=(?:100[1-9]|10[1-9]\\d|1[1-9]\\d{2}|[2-9]\\d{3}|\\d{5,})ms\\b/"
    },
    {
      "slot": 2,
      "description": "We feed web server access logs into our analytics pipeline. A valid line is one produced by either Apache or nginx in their default 'combined' format. This means it starts with an IP address (four dot-separated numbers, each 0–255), then a space, then an ident field (a hyphen if not present), then a space, then an authenticated user field (also a hyphen if not present), then a space, then a date enclosed in square brackets containing a day, a three-letter month abbreviation, a four-digit year, a colon-separated time, and a timezone offset like +0000. After another space comes the request line in double quotes: a method (upper-case letters), a space, a path that can be anything except a double quote, a space, and the protocol (which is optional). Then another space, a three-digit HTTP status code, a space, a number of bytes (digits or a hyphen), then another space, a double-quoted referrer (any characters except double quotes), a space, and finally a double-quoted user agent (any characters except double quotes). We only need the format checked; no IP validation beyond 0–255.",
      "regex": "/^(?:(?:25[0-5]|2[0-4]\\d|1\\d{2}|[1-9]?\\d)\\.){3}(?:25[0-5]|2[0-4]\\d|1\\d{2}|[1-9]?\\d) \\S+ \\S+ \\[\\d{1,2}\\/[A-Z][a-z]{2}\\/\\d{4}:\\d{2}:\\d{2}:\\d{2} [+-]\\d{4}\\] \"[A-Z]+ [^\"]* [^\"]*\" \\d{3} (?:\\d+|-|\"\") \"[^\"]*\" \"[^\"]*\"$/"
    },
    {
      "slot": 3,
      "description": "A log line that contains an error code. An error code is exactly the word 'ERR' in uppercase, followed by a hyphen, followed by exactly three decimal digits (0-9). The line is valid if this pattern appears anywhere in the line. The surrounding text can be anything, including other digits or letters. No space is allowed between 'ERR', the hyphen, and the digits.",
      "regex": "/ERR-\\d{3}/"
    },
    {
      "slot": 4,
      "description": "log line starting with ISO timestamp",
      "regex": "/^(\\d{4})-(0[1-9]|1[0-2])-(0[1-9]|[12]\\d|3[01])T([01]\\d|2[0-3]):[0-5]\\d:[0-5]\\d(?:\\.\\d+)?(?:Z|[+-](?:[01]\\d|2[0-3]):[0-5]\\d)(?: |$)/"
    },
    {
      "slot": 5,
      "description": "We need to detect failure notations in our server logs. A log line is considered to contain an error code if it includes an error token anywhere. An error token is either the literal text 'HTTP' followed by a slash, then any digits, then a space, and then one of the three-digit HTTP error status codes (400–599), bounded by word boundaries; or the literal text 'SYS' immediately followed by a hyphen and exactly three decimal digits, and this token must not be immediately preceded by a word character. The surrounding text can be anything. Both kinds of tokens are considered error codes.",
      "regex": "/\\bHTTP\\/\\d+ (?:[45]\\d{2})\\b|(?<!\\w)SYS-\\d{3}/"
    }
  ]
}

