      "slot": 5,
      "description": "python version specifier with pre-release, post-release, dev-release and local version labels",
      "regex": "/^(===|==|!=|~=|<=|>=|<|>)(?:(?:0|[1-9]\\d*)(?:\\.(?:0|[1-9]\\d*))*)(?:(?:[-._]?(?:a|b|c|rc|alpha|beta|pre|preview)[-._]?(?:0|[1-9]\\d*)?))?(?:(?:[-._]?(?:post|rev|r)[-._]?(?:0|[1-9]\\d*)?))?(?:(?:[-._]?dev[-._]?(?:0|[1-9]\\d*)?))?(?:\\+[a-z0-9]+(?:[-._][a-z0-9]+)*)?$/i"
    }
  ]
}

