{
  "items": [
    {
      "slot": 1,
      "description": "A CSV row must contain exactly three fields, separated by commas. Each field is either empty or consists of one or more characters that are not commas or newlines.",
      "regex": "/^[^,\\r\\n]*,[^,\\r\\n]*,[^,\\r\\n]*$/"
    },
    {
      "slot": 2,
      "description": "A JSON Web Token consists of three parts separated by periods. Each part is a non-empty sequence of Base64URL characters (letters, digits, hyphen, or underscore).",
      "regex": "/^[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+$/"
    },
    {
      "slot": 3,
      "description": "A CSV row must have exactly five fields separated by commas. Each field may be empty. A field containing a comma must be enclosed in double quotes. Inside a quoted field, a double quote is escaped by doubling it (e.g., \"\"). Unquoted fields cannot contain commas, double quotes, or newlines.",
      "regex": "/^(?:(?:\"(?:[^\"]|\"\")*\"|[^,\"\\r\\n]*)(?:,(?:\"(?:[^\"]|\"\")*\"|[^,\"\\r\\n]*)){4})$/"
    },
    {
      "slot": 4,
      "description": "Validate a CSV row with exactly eight fields separated by commas. Any field may be enclosed in double quotes, and if it is, then any embedded double quote must be doubled. Fields that are not enclosed in double quotes cannot contain commas or double quotes. Newlines are not allowed anywhere.",
      "regex": "/^(?:\"(?:[^\"]|\"\")*\"|[^,\"\\r\\n]*)(?:,(?:\"(?:[^\"]|\"\")*\"|[^,\"\\r\\n]*)){7}$/"
    },
    {
      "slot": 5,
      "description": "A JWT (JSON Web Token) has three Base64URL-encoded parts joined by dots. Each part must be non-empty and may only contain letters, digits, hyphens, and underscores.",
      "regex": "/^[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+$/"
    }
  ]
}

{
  "items": [
