{
  "items": [
    {
      "slot": 1,
      "description": "Validate a price in French format: digits with thousands separated by a space (or a non-breaking space U+00A0 or U+202F), decimal part after a comma with exactly two digits, followed by a space and the euro sign. Thousands groups must be exactly three digits. The integer part may be omitted if the decimal part is present. Examples of valid: '1 234,56 €', '1 234,56 €', '0,99 €'. Invalid: '1 234,5 €' (one decimal), '1234,56 €' (no thousands separator), '1 234,56€' (no space before €).",
      "regex": "/^\\d{1,3}(?:[ \\u00A0\\u202F]\\d{3})*,\\d{2} €$/u"
    },
    {
      "slot": 2,
      "description": "Validate a French formatted euro price. Requirements: The integer part may contain thousands separated by a space, a non-breaking space (U+00A0), or a narrow no-break space (U+202F). Groups must be exactly three digits. The decimal separator is a comma followed by exactly two digits. The euro sign must be preceded by a regular space. Additionally, if the integer part is zero, it may be omitted only if the decimal part is present, but the decimal part must not be empty. Exactly one euro sign at the end. No leading zeros allowed unless the integer part is exactly '0'. The entire string must be anchored. For example, '0,99 €' is valid, but '00,99 €' and ',99 €' are not.",
      "regex": "/^(?:0|[1-9]\\d{0,2}(?:[ \\u00A0\\u202F]\\d{3})*),\\d{2} €$/u"
    },
    {
      "slot": 3,
      "description": "Validate a simple French formatted euro price: one or more digits, a comma, exactly two digits, a space, and the euro sign. Thousands separators are not allowed.",
      "regex": "/^\\d+,\\d{2} €$/"
    },
    {
      "slot": 4,
      "description": "We need to validate an amount string that starts with an ISO 4217 currency code (three uppercase letters) followed by a space and a decimal number with exactly two decimal places. The number may have thousands separators as commas or spaces, but groups must be exactly three digits. The integer part must not have leading zeros unless it is exactly zero. The decimal part is required. The entire string must match. Examples: 'USD 1,234.56', 'EUR 0.99', 'JPY 1 000.00'. Invalid: 'usd 100.00' (lowercase), 'USD 100' (no decimals), 'USD 1,23.45' (wrong grouping).",
      "regex": "/^[A-Z]{3} (?:0|[1-9]\\d{0,2}(?:[ ,]\\d{3})*)\\.\\d{2}$/"
    },
    {
      "slot": 5,
      "description": "Match an amount in accounting format where negative values are enclosed in parentheses. A negative amount is a minus sign? No, parentheses. The amount must have exactly two decimal places, optional thousands separators (commas), and no currency symbol. The number part must be anchored. For example, (1,234.56) is valid, but (1234.56) is also valid? Actually, thousands separators are optional. Also, leading zeros are not allowed unless the number is less than 1. The decimal part is required. The entire string must be either a positive amount or a negative amount in parentheses. Spaces are not allowed. Ensure that the parentheses are balanced and only appear for negatives.",
      "regex": "/^(?:\\(\\d{1,3}(?:,\\d{3})*\\.\\d{2}\\)|\\d{1,3}(?:,\\d{3})*\\.\\d{2})$/"
    }
  ]
}

