{
  "items": [
    {
      "slot": 1,
      "description": "A passphrase must contain at least four words separated by single spaces. Each word consists of one or more letters (a-z or A-Z) or digits (0-9). No leading or trailing spaces are allowed.",
      "regex": "/^[A-Za-z0-9]+(?: [A-Za-z0-9]+){3,}$/"
    },
    {
      "slot": 2,
      "description": "A password must be at least 12 characters long, contain at least one uppercase letter, at least one lowercase letter, at least one digit, and at least one of the following special characters: !@#$%^&*. It must not contain any whitespace.",
      "regex": "/^(?=.*[A-Z])(?=.*[a-z])(?=.*\\d)(?=.*[!@#$%^&*])\\S{12,}$/"
