{
  "items": [
    {
      "slot": 1,
      "description": "list of numeric key=value pairs separated by ampersands, at least one pair, keys and values are one or more digits, no spaces around the ampersands",
      "regex": "/^(\\d+=\\d+)(&\\d+=\\d+)*$/"
    },
    {
      "slot": 2,
      "description": "list of lowercase alphabetic key=value pairs separated by ampersands, at least one pair, keys and values are one or more lowercase letters, no spaces around the ampersands",
