    },
    {
      "slot": 3,
      "description": "we need to store images uploaded by users as Base64 strings in our database. The string must be valid standard Base64: it can contain A-Z, a-z, 0-9, +, and /, and it may end with zero, one, or two padding equals signs. It must not contain whitespace or line breaks. The length must be a multiple of 4, except when there is no padding, in which case the length modulo 4 must not be 1.",
      "regex": "/^(?:[A-Za-z0-9+\\/]{4})*(?:[A-Za-z0-9+\\/]{2}==|[A-Za-z0-9+\\/]{3}=|[A-Za-z0-9+\\/]{2,3})?$/"
    },
