      "slot": 4,
      "description": "A product analytics service accepts a JSON array of up to 12 decimal integers from -100 to 100 inclusive. The input must be exactly one such array with no leading or trailing whitespace. The array may be empty. Numbers are written without leading zeros except for the single digit 0, with an optional minus sign for negatives, and elements are separated by a comma followed by an optional single space.",
      "regex": "/^\\[(?:-?(?:0|[1-9]\\d?|100)(?:, ?-?(?:0|[1-9]\\d?|100)){0,11})?\\]$/"
