{
  "items": [
    {
      "slot": 1,
      "description": "A price string per the following constraints:\n- Must start with a currency symbol from this set: €, £, ¥, $.\n- After the symbol, an amount with exactly two decimal places.\n- The integer part must be 1 to 3 digits with no leading zero unless the integer part is exactly 0.\n- No thousands separators.\n- No whitespace.\nValid examples: \"€12.34\", \"£0.99\", \"¥999.00\". Invalid examples: \"12.34\", \"€1234.56\", \"€01.23\", \"€12.3\", \"€12.345\".",
      "regex": "/^[€£¥$](?:0|[1-9]\\d{0,2})\\.\\d{2}$/"
    },
    {
      "slot": 2,
      "description": "We need to collect item prices in our storefront's admin panel. Each price is a plain number with a period as decimal separator and exactly two digits after the decimal point, no currency symbol, no commas, no spaces. Values below one dollar are allowed but must include the leading zero. The whole field is required.",
      "regex": "/^\\d+\\.\\d{2}$/"
    },
    {
      "slot": 3,
      "description": "A price string that represents a U.S. dollar amount with exactly two decimal places, using a comma as thousands separator and a period as decimal separator. The amount must be at least $1.00, must not have a leading zero before the integer part except when the integer part is a single zero? Actually, the integer part must be 1 or more, and if it has four or more digits, groups of three digits must be separated by commas, starting from the right. The dollar sign is required. No spaces are allowed.",
      "regex": "/^\\$(?:[1-9]\\d{0,2}|[1-9]\\d{0,2}(?:,\\d{3})+)\\.\\d{2}$/"
    },
    {
      "slot": 4,
      "description": "An accounting-style amount string representing a negative monetary value. Rules:\n- The amount is enclosed in parentheses.\n- Inside the parentheses, there is an optional currency symbol from: $, €, £, ¥.\n- Then the numeric part: one or more digits for the integer part, no leading zeros unless the integer part is exactly 0.\n- A required decimal point followed by exactly two digits.\n- No spaces anywhere.\nValid: \"($123.45)\", \"(€0.99)\", \"(123.45)\". Invalid: \"$123.45\", \"($123.4)\", \"($01.23)\", \"( $123.45 )\".",
      "regex": "/^\\((?:[$€£¥])?(?:0|[1-9]\\d*)\\.\\d{2}\\)$/"
    },
    {
      "slot": 5,
      "description": "For our invoicing system, negative amounts are written in accounting format: the number is wrapped in parentheses, and no minus sign is used. The amount may optionally include a currency symbol before the number. The number must have exactly two decimal places and may contain commas as thousands separators. The integer part must not have leading zeros (unless it is a single zero? Actually, for negative amounts, zero is allowed but must be written as 0, not 00). No spaces are allowed. We only need to validate the format, not the actual value.",
      "regex": "/^\\((?:[$€£¥])?(?:0|[1-9]\\d{0,2}(?:,\\d{3})*|[1-9]\\d*)\\.\\d{2}\\)$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "A string is valid if it represents an even integer. The string may optionally start with a minus sign, followed by one or more digits. No leading zeros are allowed unless the number is exactly zero. For example, \"0\", \"2\", \"-4\", \"10\" are valid; \"01\", \"1.0\", \"abc\" are invalid.",
      "regex": "/^-?(?:0|[1-9][0-9]*[02468])$/"
    },
    {
      "slot": 2,
      "description": "even integer, no leading zeros, optional minus sign",
      "regex": "/^-?(?:0|[1-9][0-9]*[02468])$/"
    },
    {
      "slot": 3,
      "description": "We need to validate numbers in scientific notation for a scientific data input field. The format should be: an optional sign (+ or -), followed by a non-zero digit, then optionally a decimal point and one or more digits, then 'e' or 'E', an optional sign (+ or -), and one or more digits. The number part must have at least one digit before the exponent. For example: \"1e10\", \"-2.5E-3\", \"+3.14e+2\" are valid. Invalid: \"e10\", \"1e\", \"1e+\", \".5e3\", \"1.e3\".",
      "regex": "/^[+-]?[1-9]\\d*(\\.\\d+)?[eE][+-]?\\d+$/"
    },
    {
      "slot": 4,
      "description": "An integer between 1 and 100 inclusive. The string must consist of only digits, with no leading zeros except for the number zero itself (which is not allowed here). Valid examples: \"1\", \"50\", \"100\". Invalid: \"0\", \"101\", \"01\".",
      "regex": "/^(?:[1-9]|[1-9][0-9]|100)$/"
    },
    {
      "slot": 5,
      "description": "integer 1 to 100 inclusive, no leading zeros",
      "regex": "/^(?:[1-9]|[1-9][0-9]|100)$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "match a 12-hour clock time: 1 or 2 digit hour 1-12, optional colon or dot, then 2 digit minutes 00-59, optional colon or dot, then 2 digit seconds 00-59, optional AM/PM case-insensitive, allow a space before the meridiem indicator",
      "regex": "/^(0?[1-9]|1[0-2])(?:[:.]?[0-5][0-9](?:[:.]?[0-5][0-9])?)?\\s?[ap]m$/i"
    },
    {
      "slot": 2,
      "description": "Our system needs to accept dates in the European format with slashes as separators, where the day is one or two digits, the month is one or two digits, and the year is exactly four digits. The date must be a valid calendar date (e.g., February 30 is not allowed), but we do not need to check leap years.",
      "regex": "/^(0?[1-9]|[12][0-9]|3[01])\\/(0?[1-9]|1[0-2])\\/\\d{4}$/"
    },
    {
      "slot": 3,
      "description": "We need to validate a month abbreviation field in our legacy system. Accept any three-letter English month abbreviation (Jan, Feb, Mar, Apr, May, Jun, Jul, Aug, Sep, Oct, Nov, Dec) case-insensitively. The field must contain exactly the three-letter abbreviation without any trailing period or other characters.",
      "regex": "/^(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)$/i"
    },
    {
