    {
      "slot": 1,
      "description": "We need a field to capture the version tag of a release. The tag must start with a lowercase 'v', followed by a major version number (one or more digits), then a dot, then a minor version number (one or more digits). Optionally, a patch number can be included after another dot; if present, it must be one or more digits. No other characters are allowed.",
      "regex": "/^v\\d+\\.\\d+(\\.\\d+)?$/"
    },
    {
      "slot": 2,
      "description": "Validate a calendar version string in the format YYYY.MM, where YYYY is a four-digit year (any four digits) and MM is a two-digit month from 01 to 12. The separator is a dot. No other characters are allowed.",
      "regex": "/^\\d{4}\\.(0[1-9]|1[0-2])$/"
    },
    {
      "slot": 3,
      "description": "Our release tags must follow semantic versioning with a 'v' prefix. The tag must start with a lowercase 'v', followed by a major, minor, and patch number, each being one or more digits without leading zeros (except the number zero itself). The three parts are separated by dots. Additionally, a pre-release identifier may be appended after a hyphen; it consists of one or more dot-separated alphanumeric identifiers, where each identifier is either numeric (without leading zeros unless it is zero) or alphanumeric containing at least one letter. No build metadata is allowed.",
      "regex": "/^v(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-((?:0|[1-9]\\d*|\\d*[a-zA-Z-][a-zA-Z0-9-]*)(?:\\.(?:0|[1-9]\\d*|\\d*[a-zA-Z-][a-zA-Z0-9-]*))*))?$/"
