    {
      "slot": 1,
      "description": "Our support dashboard shows the IPv6 address a customer's router reports. We need to check the address field before saving, but we only accept the full written-out form: eight groups of exactly four hexadecimal digits separated by colons. No shortened '::' form, no omitted leading zeros, and no mixed IPv4 notation.",
      "regex": "/^(?:[0-9A-Fa-f]{4}:){7}[0-9A-Fa-f]{4}$/"
    },
    {
      "slot": 2,
      "description": "Validate an IPv4 address string according to the following format rules:\n- Four decimal octets separated by dots.\n- Each octet is 0 to 255.\n- No leading zeros are allowed (so '01' is invalid, but '0' is valid).\n- The whole string must be exactly the address, with no surrounding whitespace or extra characters.\nNote: this is a format check only; no checksum or reachability is verified.",
      "regex": "/^(?:(?:25[0-5]|2[0-4]\\d|1\\d{2}|[1-9]?\\d)\\.){3}(?:25[0-5]|2[0-4]\\d|1\\d{2}|[1-9]?\\d)$/"
    },
    {
      "slot": 3,
      "description": "Match an IPv4 address: four decimal numbers from 0 to 255 separated by dots, with no leading zeros and nothing else around it.",
      "regex": "/^(?:(?:25[0-5]|2[0-4]\\d|1\\d{2}|[1-9]?\\d)\\.){3}(?:25[0-5]|2[0-4]\\d|1\\d{2}|[1-9]?\\d)$/"
    },
    {
      "slot": 4,
      "description": "We collect hardware MAC addresses from field devices. The form should accept a MAC address written as six pairs of hexadecimal digits, but the separator must be consistent throughout: either colons between every pair or hyphens between every pair. We do not want mixed separators like colons in one place and hyphens in another, and no other characters are allowed.",
      "regex": "/^(?:[0-9A-Fa-f]{2}(?::[0-9A-Fa-f]{2}){5}|[0-9A-Fa-f]{2}(?:-[0-9A-Fa-f]{2}){5})$/"
    },
    {
      "slot": 5,
      "description": "full ipv6 address 8 groups of 4 hex digits",
      "regex": "/^(?:[0-9A-Fa-f]{4}:){7}[0-9A-Fa-f]{4}$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "Our checkout form needs to validate US shipping addresses. The ZIP field should accept either a standard five-digit ZIP code or the extended ZIP+4 format with a hyphen separating the five-digit part and the four-digit extension.",
      "regex": "/^\\d{5}(?:-\\d{4})?$/"
    },
    {
      "slot": 2,
      "description": "Validate a US ZIP code, which is either exactly five digits or five digits followed by a hyphen and four more digits.",
      "regex": "/^\\d{5}(?:-\\d{4})?$/"
    },
    {
      "slot": 3,
      "description": "Validate the format of a German IBAN. Rules:\n- Must start with the country code 'DE' followed by two check digits.\n- After the check digits, exactly 18 digits (the account number and bank code combined, no spaces).\n- The check digits are not validated for correctness; only the format is checked.",
      "regex": "/^DE\\d{20}$/"
    },
    {
      "slot": 4,
      "description": "canadian postal codes",
      "regex": "/^[A-Za-z]\\d[A-Za-z][ -]?\\d[A-Za-z]\\d$/"
    },
    {
      "slot": 5,
      "description": "Accept a US ZIP code in either of these formats:\n1. Five digits.\n2. Five digits followed by a hyphen and four digits.\nNo other characters are allowed.",
      "regex": "/^\\d{5}(?:-\\d{4})?$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "Our signup form requires a password that is at least 8 characters long and contains at least one lowercase letter, one uppercase letter, and one digit. No other characters are allowed.",
      "regex": "/^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)[A-Za-z\\d]{8,}$/"
    },
    {
      "slot": 2,
      "description": "api key format: sk_ followed by exactly 32 hex chars",
      "regex": "/^sk_[0-9a-f]{32}$/"
    },
    {
      "slot": 3,
      "description": "password 8+ chars no whitespace no 3 identical consecutive chars",
      "regex": "/^(?!.*\\s)(?!.*(.)\\1\\1).{8,}$/"
    },
    {
      "slot": 4,
      "description": "Password policy:\n- Must be at least 10 characters long.\n- Must contain at least one lowercase letter, one uppercase letter, one digit, and one special character from !@#$%^&*.\n- Must not contain the word 'password' (case-insensitive).\n- No whitespace characters allowed.",
      "regex": "/^(?!.*password)(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)(?=.*[!@#$%^&*])[^\\s]{10,}$/i"
    },
    {
      "slot": 5,
      "description": "We need our password field to accept only passwords that are at least 10 characters long and do not contain any spaces or tabs, and do not have three identical characters in a row.",
      "regex": "/^(?!.*[\\t ])(?!.*(.)\\1\\1).{10,}$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "A line that is a TODO or FIXME comment. It may start with optional whitespace, then //, #, or /*, then optional whitespace, then TODO or FIXME (case insensitive), then optionally a colon or space and any other characters except newline. The comment marker and TODO/FIXME keyword must be present.",
      "regex": "/^\\s*(?:\\/\\/|#|\\/\\*)\\s*(?:TODO|FIXME)\\b.*$/i"
    },
    {
      "slot": 2,
      "description": "Our code review tool needs to automatically detect TODO or FIXME markers in source files. A marker is considered present if a line contains a comment that starts with // or #, followed by optional spaces, then the word TODO or FIXME in any case. The rest of the line is ignored.",
      "regex": "/^\\s*(?:\\/\\/|#)\\s*(?:TODO|FIXME)\\b.*$/i"
    },
    {
      "slot": 3,
      "description": "A valid identifier name in either snake_case or SCREAMING_SNAKE_CASE: it must start with a letter or underscore, followed by letters, digits, or underscores. It may optionally be entirely uppercase with underscores. No hyphens or spaces allowed.",
      "regex": "/^[A-Za-z_][A-Za-z0-9_]*(?:[A-Z][A-Z0-9_]*)?$/"
    },
    {
      "slot": 4,
      "description": "kebab-case name: lowercase words separated by hyphens, no leading or trailing hyphen, no consecutive hyphens.",
      "regex": "/^[a-z]+(?:-[a-z]+)*$/"
    },
    {
      "slot": 5,
      "description": "An environment variable name as used in POSIX shell: it must start with an uppercase letter or underscore, followed by zero or more uppercase letters, digits, or underscores. Only uppercase allowed.",
      "regex": "/^[A-Z_][A-Z0-9_]*$/"
    }
  ]
}

