      "slot": 2,
      "description": "A positive integer, with no leading zeros, unless the number is exactly zero.",
      "regex": "/^(0|[1-9][0-9]*)$/"
    },
    {
      "slot": 3,
      "description": "A percentage value from 0 to 100 inclusive, allowing up to two decimal places.",
      "regex": "/^(100(\\.0{1,2})?|(\\d{1,2})(\\.\\d{1,2})?)$/"
    },
    {
      "slot": 4,
      "description": "A number in scientific notation, with the following constraints: The significand must be a decimal number (i.e., it must contain a decimal point) with at least one digit before and after the decimal point. The significand must not have leading zeros unless it is exactly zero (e.g., '0.5' is allowed, but '00.5' is not). The exponent is optional; if present, it must be the letter 'E' (uppercase only) followed by an integer (with optional '+' or '-') with no leading zeros. The exponent must not be zero. The entire string must match exactly.",
      "regex": "/^(0|[1-9]\\d*)\\.\\d+(E[+-]?[1-9]\\d*)?$/"
