      "description": "The authentication gateway forwards tokens straight from our identity provider as compact serialized tokens: exactly three non-empty URL-safe Base64 segments joined by single dots, with no padding characters and nothing before or after. The header and payload segments are Base64URL-encoded JSON and must be non-empty; the signature segment must also be non-empty. We only check the shape here, the signature is verified elsewhere.",
      "regex": "/^[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+$/"
    },
    {
      "slot": 3,
      "description": "Validate a compact JWS token string. Constraints: (1) the string consists of exactly three parts separated by periods; (2) each part is one or more characters from the Base64URL alphabet: A-Z, a-z, 0-9, hyphen, underscore; (3) padding with '=' is not allowed; (4) no characters outside that alphabet may appear, including whitespace; (5) no leading or trailing period. Only the lexical shape is required; the signature is not verified.",
      "regex": "/^[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+$/"
    },
    {
      "slot": 4,
      "description": "simple xml-ish tag pair with matching name",
      "regex": "/^<([A-Za-z_][\\w.-]*)(?: [^<>]*)?>.*<\\/\\1>$/s"
    },
    {
      "slot": 5,
      "description": "json array of ints, no spaces at all, may be empty",
      "regex": "/^\\[(?:-?\\d+(?:,-?\\d+)*)?\\]$/"
    }
  ]
}
