{
  "items": [
    {
      "slot": 1,
      "description": "Validates an ISO 8601 duration string that may include years, months, days, hours, minutes, and seconds in that order. Each component is optional, but at least one must be present. A leading 'P' is required, and if time components are included, they must be preceded by a 'T'. The duration must not include weeks.",
      "regex": "/^P(?=\\d|T\\d)(?:\\d+Y)?(?:\\d+M)?(?:\\d+D)?(?:T(?=\\d)(?:\\d+H)?(?:\\d+M)?(?:\\d+(?:\\.\\d+)?S)?)?$/"
    },
    {
      "slot": 2,
      "description": "european date dd/mm/yyyy",
      "regex": "/^(0[1-9]|[12][0-9]|3[01])\\/(0[1-9]|1[0-2])\\/\\d{4}$/"
    },
    {
      "slot": 3,
      "description": "Validates an ISO 8601 duration string that may include weeks or other date/time components. A leading 'P' is required. The duration may contain weeks alone or years, months, days, hours, minutes, and seconds in order, but weeks cannot be combined with other components. If time components are included, they must be preceded by a 'T'. At least one component must be present.",
      "regex": "/^P(?=\\d|T\\d)(?:\\d+W|(?:\\d+Y)?(?:\\d+M)?(?:\\d+D)?(?:T(?=\\d)(?:\\d+H)?(?:\\d+M)?(?:\\d+(?:\\.\\d+)?S)?)?)$/"
    },
    {
      "slot": 4,
      "description": "iso 8601 duration like p3dt4h",
      "regex": "/^P(?=\\d|T\\d)(?:\\d+Y)?(?:\\d+M)?(?:\\d+D)?(?:T(?=\\d)(?:\\d+H)?(?:\\d+M)?(?:\\d+(?:\\.\\d+)?S)?)?$/"
    },
    {
      "slot": 5,
      "description": "Validate a US date in MM/DD/YYYY or MM-DD-YYYY format. The separator must be consistent. The month is between 01 and 12, the day is between 01 and 31, and the year is exactly four digits. Calendar correctness (e.g., days per month, leap years) is not checked.",
      "regex": "/^(0[1-9]|1[0-2])([\\/-])(0[1-9]|[12][0-9]|3[01])\\2\\d{4}$/"
    }
  ]
