{
  "items": [
    {
      "slot": 1,
      "description": "Our project management tool stores task durations as ISO 8601 duration strings. We need to validate that a duration string is well-formed. The format starts with P, followed by an optional number of years, months, weeks, days, hours, minutes, and seconds. At least one component must be present. The components can appear in any order, but each can appear at most once. The number part is a non-negative integer, and the letter part is one of Y, M, W, D, H, S. The time part, if present, is preceded by T. Only the format is checked; we don't care about the actual length of months or years.",
      "regex": "/^P(?=\\d|T\\d)(?:\\d+Y)?(?:\\d+M)?(?:\\d+W)?(?:\\d+D)?(?:T(?:\\d+H)?(?:\\d+M)?(?:\\d+S)?)?$/"
    },
    {
      "slot": 2,
      "description": "european date dd/mm/yyyy, allow single digit day/month",
