{
  "items": [
    {
      "slot": 1,
      "description": "Validate a social media handle. Rules:\n1. Must start with the @ symbol.\n2. The first character after @ must be a letter (a-z, A-Z) or an underscore.\n3. Subsequent characters may be letters, digits, underscores, or periods.\n4. Must end with a letter or digit (no trailing underscore or period).\n5. Total length after @ must be between 3 and 15 characters inclusive.\n6. Only ASCII characters allowed.",
      "regex": "/^@[A-Za-z_][A-Za-z0-9_.]{1,13}[A-Za-z0-9]$/"
    },
    {
      "slot": 2,
      "description": "email address not at gmail yahoo hotmail outlook",
      "regex": "/^[A-Za-z0-9._%+-]+@(?!(?:gmail|yahoo|hotmail|outlook)\\.)[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$/i"
    },
    {
      "slot": 3,
      "description": "Validate an email address for a web form, using a practical subset of RFC 5322:\n- Local part: one or more characters from A-Z a-z 0-9 and the symbols . _ % + - . The local part must not start or end with a dot, and must not contain two consecutive dots.\n- Exactly one @ separating local part and domain.\n- Domain: one or more labels separated by dots. Each label consists of letters, digits, and hyphens, must start and end with a letter or digit, and must be 1 to 63 characters long.\n- The top-level domain must be at least 2 characters and contain only letters.\n- Total length must not exceed 254 characters.\n- Matching is case-insensitive.",
      "regex": "/^(?=.{1,254}$)(?=[^@]{1,64}@)[A-Za-z0-9!#$%&'*+\\/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+\\/=?^_`{|}~-]+)*@(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\\.)+[A-Za-z]{2,}$/"
    },
    {
      "slot": 4,
      "description": "We need to validate the email address field in our signup form. The format must be a standard email address with a local part of letters, digits, and the characters . _ % + - (but not starting or ending with a dot and no consecutive dots), followed by @, then a domain with at least one dot, where each label contains only letters, digits, and hyphens and starts and ends with a letter or digit. The last label (TLD) must be at least two letters. Case-insensitive.",
      "regex": "/^[A-Za-z0-9_%+-]+(?:\\.[A-Za-z0-9_%+-]+)*@[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?(?:\\.[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?)*\\.[A-Za-z]{2,}$/i"
    },
    {
      "slot": 5,
      "description": "practical email address",
      "regex": "/^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$/"
    }
  ]
}

{
