{
  "items": [
    {
      "slot": 1,
      "description": "A simplified five-field cron expression with fields for minute, hour, day of month, month, and day of week, separated by single spaces. Each field can contain digits, commas, hyphens, asterisks, and forward slashes, with no other characters.",
      "regex": "/^[\\d*,/-]+(?: [\\d*,/-]+){4}$/"
    },
    {
      "slot": 2,
      "description": "Our commit messages must follow the Conventional Commits format: a type, an optional scope in parentheses, an optional exclamation mark for breaking changes, a colon and space, and a non-empty description. Types are feat, fix, docs, style, refactor, perf, test, chore, ci, and build. The scope, if present, may contain any characters except parentheses and must not be empty. The description must not be empty.",
      "regex": "/^(?:feat|fix|docs|style|refactor|perf|test|chore|ci|build)(?:\\([^()]+\\))?!?: .+$/i"
    },
    {
      "slot": 3,
      "description": "Validate a five-field cron expression (minute, hour, day of month, month, day of week) separated by single spaces. Each field must be one of the following forms: a single number, a range (two numbers separated by a hyphen), a list of comma-separated numbers or ranges, or a step (a base number, range, or asterisk followed by a slash and a positive step number). Numbers must not have leading zeros unless the number is exactly 0. The minute field is 0–59, hour 0–23, day of month 1–31, month 1–12, day of week 0–6. Asterisk is allowed in any field, and in the day-of-week field 7 is also allowed (Sunday). No whitespace other than the single spaces separating fields.",
      "regex": "/^(?:(?:0|[1-5]?\\d)(?:-(?:0|[1-5]?\\d))?(?:\\/(?:[1-9]\\d*))?|\\*(?:\\/(?:[1-9]\\d*))?)(?:,(?:(?:0|[1-5]?\\d)(?:-(?:0|[1-5]?\\d))?(?:\\/(?:[1-9]\\d*))?|\\*(?:\\/(?:[1-9]\\d*))?))* (?:(?:0|1?\\d|2[0-3])(?:-(?:0|1?\\d|2[0-3]))?(?:\\/(?:[1-9]\\d*))?|\\*(?:\\/(?:[1-9]\\d*))?)(?:,(?:(?:0|1?\\d|2[0-3])(?:-(?:0|1?\\d|2[0-3]))?(?:\\/(?:[1-9]\\d*))?|\\*(?:\\/(?:[1-9]\\d*))?))* (?:(?:[1-9]|[12]\\d|3[01])(?:-(?:[1-9]|[12]\\d|3[01]))?(?:\\/(?:[1-9]\\d*))?|\\*(?:\\/(?:[1-9]\\d*))?)(?:,(?:(?:[1-9]|[12]\\d|3[01])(?:-(?:[1-9]|[12]\\d|3[01]))?(?:\\/(?:[1-9]\\d*))?|\\*(?:\\/(?:[1-9]\\d*))?))* (?:(?:[1-9]|1[0-2])(?:-(?:[1-9]|1[0-2]))?(?:\\/(?:[1-9]\\d*))?|\\*(?:\\/(?:[1-9]\\d*))?)(?:,(?:(?:[1-9]|1[0-2])(?:-(?:[1-9]|1[0-2]))?(?:\\/(?:[1-9]\\d*))?|\\*(?:\\/(?:[1-9]\\d*))?))* (?:(?:[0-6])(?:-(?:[0-6]))?(?:\\/(?:[1-9]\\d*))?|7|\\*(?:\\/(?:[1-9]\\d*))?)(?:,(?:(?:[0-6])(?:-(?:[0-6]))?(?:\\/(?:[1-9]\\d*))?|7|\\*(?:\\/(?:[1-9]\\d*))?))*$/"
    },
    {
      "slot": 4,
      "description": "Our pull request titles must start with a ticket key like ABC-123 followed by a colon and space, then a conventional commit type (feat, fix, chore, docs, refactor, test, or perf), an optional scope in parentheses, an optional exclamation mark, another colon and space, and a non-empty description. The whole title is case-sensitive.",
      "regex": "/^[A-Z]{2,}-\\d+: (?:feat|fix|chore|docs|refactor|test|perf)(?:\\([^()]+\\))?!?: .+$/"
    },
    {
      "slot": 5,
      "description": "Git branch names must use the format type/description. The type must be one of feature, bugfix, hotfix, release, or chore. The description must contain only lowercase letters, digits, and hyphens, and must not start or end with a hyphen. The whole branch name must not contain spaces.",
      "regex": "/^(?:feature|bugfix|hotfix|release|chore)\\/(?!-)[a-z0-9]+(?:-[a-z0-9]+)*$/"
    }
  ]
}

