      "regex": "/^https?:\\/\\/(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\\.)+[a-z]{2,}(?::\\d{1,5})?(?:\\/[^\\s]*)?(?:\\?[^\\s]*)?$/i"
