{
  "items": [
    {
      "slot": 1,
      "description": "Validate an email address in a practical, non-RFC-complete way.\n\nRules:\n1. The local part (before the @) must be 1 to 64 characters long and may contain letters (a-z, A-Z), digits (0-9), and the following special characters: dot (.), hyphen (-), underscore (_), plus (+).\n2. The local part must not start or end with a dot, and must not contain two consecutive dots.\n3. There must be exactly one @ symbol separating the local part and the domain.\n4. The domain must consist of one or more labels separated by dots. Each label must start and end with a letter or digit, may contain letters, digits, and hyphens, and must be 1 to 63 characters long.\n5. The domain must end with a top-level domain (TLD) that is at least 2 characters long and consists only of letters.\n6. The entire address must be no longer than 254 characters.\n7. The check is case-insensitive.",
      "regex": "/^(?=.{1,254}$)(?=[^@]{1,64}@)[a-zA-Z0-9!#$%&'*+\\/=?^_`{|}~-]+(?:\\.[a-zA-Z0-9!#$%&'*+\\/=?^_`{|}~-]+)*@(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\\.)+[a-zA-Z]{2,}$/i"
    },
    {
      "slot": 2,
      "description": "We need to validate usernames for our new platform. A valid username must be between 3 and 16 characters long, can only contain letters (a-z, A-Z), numbers (0-9), and underscores, and must start with a letter. It cannot end with an underscore.",
      "regex": "/^[a-zA-Z][a-zA-Z0-9_]{1,14}[a-zA-Z0-9]$/"
    },
    {
      "slot": 3,
      "description": "Match an email address that belongs to the domain example.com. The local part can be any sequence of letters, digits, dots, hyphens, underscores, or plus signs, but it cannot start or end with a dot, and it cannot contain two consecutive dots. The domain must be exactly example.com.",
      "regex": "/^(?!\\.)(?!.*\\.\\.)(?!.*\\.@)[a-zA-Z0-9._+-]+@example\\.com$/"
    },
    {
      "slot": 4,
      "description": "twitter handle starting with @, 1-15 alphanumeric or underscore chars after @",
      "regex": "/^@[a-zA-Z0-9_]{1,15}$/"
    },
    {
      "slot": 5,
      "description": "Validate an email address that is not from a free webmail provider.\n\nRules:\n1. The address must follow the standard practical email format: local part (letters, digits, dots, hyphens, underscores, plus signs; no leading/trailing dot, no consecutive dots) @ domain (one or more dot-separated labels, each starting and ending with alphanumeric, hyphens allowed inside, TLD at least 2 letters).\n2. The domain must not be one of the following free webmail domains: gmail.com, yahoo.com, hotmail.com, outlook.com, aol.com, icloud.com, mail.com, protonmail.com, zoho.com, yandex.com.\n3. The check is case-insensitive for the domain part.",
      "regex": "/^(?=.{1,254}$)(?=[^@]{1,64}@)[a-zA-Z0-9!#$%&'*+\\/=?^_`{|}~-]+(?:\\.[a-zA-Z0-9!#$%&'*+\\/=?^_`{|}~-]+)*@(?!gmail\\.com$|yahoo\\.com$|hotmail\\.com$|outlook\\.com$|aol\\.com$|icloud\\.com$|mail\\.com$|protonmail\\.com$|zoho\\.com$|yandex\\.com$)(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\\.)+[a-zA-Z]{2,}$/i"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "We need to scan source files for TODO or FIXME comments. A valid comment starts at the beginning of a line (after optional spaces) with // or /*, followed by TODO or FIXME (case-insensitive), and then any characters until the end of the line.",
      "regex": "/^[ \\t]*(?:\\/\\/|\\/\\*)[ \\t]*(?:TODO|FIXME)\\b.*$/im"
    },
    {
      "slot": 2,
      "description": "Kebab-case name: all lowercase words separated by single hyphens, no leading or trailing hyphens, no consecutive hyphens, at least two characters.",
      "regex": "/^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/"
    },
    {
      "slot": 3,
      "description": "import statement of react module",
      "regex": "/^import\\s+.*\\s+from\\s+['\"]react['\"];?$/"
    },
    {
      "slot": 4,
      "description": "Our style guide requires that variable names be camelCase. We need to validate that a proposed variable name starts with a lowercase letter, contains only letters and digits, and has no underscores or hyphens.",
      "regex": "/^[a-z][a-zA-Z0-9]*$/"
    },
    {
      "slot": 5,
      "description": "A valid TODO or FIXME comment line must: start at line beginning (after optional spaces/tabs), begin with // or /*, then optional whitespace, then TODO or FIXME in uppercase (case-sensitive), followed by a non-word character or end-of-line, then any characters until the line ends. The comment may not contain the word 'todo' or 'fixme' in lowercase anywhere. The comment must not be empty after the tag.",
      "regex": "/^[ \\t]*(?:\\/\\/|\\/\\*)[ \\t]*(?:TODO|FIXME)\\b(?![^\\n]*\\b(?:todo|fixme)\\b)(?=\\s|$)[^\\n]*$/m"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "Match a PEP 440 version specifier. Rules:\n1. An optional leading '==', '!=', '<=', '>=', '<', '>', or '~=' operator (default is '==').\n2. A version number consisting of one or more dot-separated numeric components, optionally followed by a pre-release segment: 'a', 'b', 'rc', 'alpha', 'beta', 'pre' or 'preview' (case-insensitive) followed by an optional number, and optionally an '.*' suffix.\n3. Alternatively, the wildcard '*' alone, or a version with a trailing '.*' wildcard (in which case no pre-release is allowed).\n4. Local version labels (after '+') are not allowed in specifiers.\nWhitespace around the specifier is allowed.",
      "regex": "/^\\s*(?:(?:==|!=|<=|>=|<|>|~=)\\s*)?(?:\\*|\\d+(?:\\.\\d+)*(?:\\.\\*)?(?:(?:a|b|rc|alpha|beta|pre|preview)\\d*)?)\\s*$/i"
    },
    {
      "slot": 2,
      "description": "Validate a PEP 440 version specifier. The specifier must start with one of the operators '==', '!=', '<=', '>=', '<', '>', or '~='. After the operator, a version string is required; it must be one or more numeric components separated by dots (e.g., '1', '2.7', '3.10.4'), followed by an optional pre-release marker from the set 'a', 'b', 'rc', 'alpha', 'beta', 'pre', 'preview' (case-insensitive) with an optional number, and an optional wildcard suffix '.*'. The wildcard only applies to the release portion and cannot be combined with a pre-release. Leading and trailing spaces are allowed.",
      "regex": "/^\\s*(?:==|!=|<=|>=|<|>|~=)\\s*\\d+(?:\\.\\d+)*(?:\\.\\*)?(?:(?:a|b|rc|alpha|beta|pre|preview)\\d*)?\\s*$/i"
    },
    {
      "slot": 3,
      "description": "python version specifier like ==1.2.* or >=2.0rc1",
      "regex": "/^(?:==|!=|<=|>=|<|>|~=)?\\d+(?:\\.\\d+)*(?:\\.\\*)?(?:(?:a|b|rc|alpha|beta|pre|preview)\\d*)?$/i"
    },
    {
      "slot": 4,
      "description": "Match a version specifier for a Python package. It must start with one of the operators ==, !=, <=, >=, <, >, or ~=, followed by a version number made of dot-separated digits, with an optional pre-release tag such as 'a', 'b', or 'rc' plus a number. Spaces before and after the whole specifier are permitted.",
      "regex": "/^\\s*(?:==|!=|<=|>=|<|>|~=)\\s*\\d+(?:\\.\\d+)*(?:(?:a|b|rc)\\d*)?\\s*$/i"
    },
    {
      "slot": 5,
      "description": "As part of our release automation pipeline, the build system must parse version strings produced by our internal tooling. Each version string must conform to the semantic versioning standard: a numeric major, minor, and patch version, optionally followed by a hyphen and a pre-release identifier (which may consist of alphanumeric characters and hyphens, separated by dots), and optionally followed by a plus sign and build metadata (also alphanumeric and hyphen characters separated by dots). The entire string must contain nothing else.",
      "regex": "/^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-((?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\\.(?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\\+([0-9a-zA-Z-]+(?:\\.[0-9a-zA-Z-]+)*))?$/"
    }
  ]
}

