    {
      "slot": 1,
      "description": "A string that consists of an opening XML-like tag, a body of text, and a closing tag with the same name. The tag name must start with a letter and contain only letters, digits, hyphens, underscores, or periods, and both tags must use exactly the same name, case-sensitive. The body may be any characters except angle brackets.",
      "regex": "/^<([A-Za-z][\\w.-]*)>[^<>]*<\\/\\1>$/"
    },
    {
      "slot": 2,
      "description": "A JSON array of numbers, where a number is an integer or decimal literal with an optional minus sign and optional fractional part. Whitespace is allowed after commas and before the closing bracket, but not required. The array may be empty, and no trailing comma is permitted.",
      "regex": "/^\\[(?:\\s*-?\\d+(?:\\.\\d+)?(?:\\s*,\\s*-?\\d+(?:\\.\\d+)?)*\\s*)?\\]$/"
    },
    {
      "slot": 3,
      "description": "A CSV row containing exactly five comma-separated fields. Each field may be empty or contain any characters except commas and newlines. Commas are the only separators; there is no quoting or escaping.",
      "regex": "/^[^,\\r\\n]*(?:,[^,\\r\\n]*){4}$/"
    },
    {
      "slot": 4,
      "description": "A JSON array of numbers, where a number is an integer or decimal literal with an optional minus sign and optional fractional part. Whitespace is allowed after commas and before the closing bracket, but not required. The array may be empty, and no trailing comma is permitted.",
      "regex": "/^\\[(?:\\s*-?\\d+(?:\\.\\d+)?(?:\\s*,\\s*-?\\d+(?:\\.\\d+)?)*\\s*)?\\]$/"
    },
    {
      "slot": 5,
      "description": "csv row exactly 3 fields, fields can be empty, no commas or line breaks inside a field",
