    },
    {
      "slot": 2,
      "description": "Conventional Commits title format: \n- type: one of feat, fix, docs, style, refactor, perf, test, chore, ci, build, revert\n- optional scope: in parentheses, one or more lowercase letters or digits or hyphens, no leading/trailing hyphen, no consecutive hyphens\n- optional ! indicating breaking change\n- colon and single space\n- description: at least one character, no newlines, may contain any printable ASCII except control characters\n- total length no more than 100 characters",
      "regex": "/^(?:feat|fix|docs|style|refactor|perf|test|chore|ci|build|revert)(?:\\([a-z0-9]+(?:-[a-z0-9]+)*\\))?!?: [^\\x00-\\x1F\\x7F]{1,100}$/",
