    {
      "slot": 5,
      "description": "A Conventional Commits title where the type is one of feat, fix, docs, style, refactor, perf, test, chore, ci, build, revert, or a custom type consisting of a single word starting with a lowercase letter and containing only lowercase letters and digits. The optional scope must be a single word of lowercase letters, digits, or hyphens, in parentheses. An optional exclamation mark indicates a breaking change. After a colon and a space, the description must have at least one character and may not start or end with whitespace, and must not contain any line breaks or tabs. The total length must not exceed 100 characters.",
      "regex": "/^(?:feat|fix|docs|style|refactor|perf|test|chore|ci|build|revert|[a-z][a-z0-9]*)(?:\\([a-z0-9-]+\\))?!?: \\S(?:[^\\r\\n\\t]*\\S)?$/",
