    {
      "slot": 4,
      "description": "Match a file name that has an image extension. Valid extensions are jpg, jpeg, png, gif, bmp, and webp. The extension must be preceded by a dot and may be in any case. The part before the dot must be non-empty and may contain any characters except a slash or backslash, but it cannot end with a dot (to avoid a double dot before the extension).",
      "regex": "/^[^\\/\\\\]+(?<!\\.)\\.(?:jpe?g|png|gif|bmp|webp)$/i"
    },
    {
      "slot": 5,
      "description": "A file name with a date prefix in the format YYYY-MM-DD, followed by an underscore and a non-empty sequence of letters, digits, underscores, or hyphens. The date format is checked but calendar validity is not (e.g., 2023-99-99 is accepted). The entire name must consist only of these characters.",
      "regex": "/^\\d{4}-\\d{2}-\\d{2}_[A-Za-z0-9_-]+$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "Our platform issues API keys to third-party developers. The key format we guarantee to partners is: the literal prefix 'sk_live_' (lowercase), immediately followed by exactly 32 characters drawn from the URL-safe base64 alphabet. That alphabet is A–Z, a–z, 0–9, hyphen and underscore. We want to reject keys with the older test prefix 'sk_test_' and keys that contain any other character. Only the shape is checked; there is no checksum.",
      "regex": "/^sk_live_[A-Za-z0-9_-]{32}$/"
    },
    {
      "slot": 2,
      "description": "Passwords for the customer portal must satisfy all of the following:\n- Total length between 10 and 64 characters inclusive;\n- May contain any printable ASCII characters except spaces and control characters (i.e. visible characters from ! to ~);\n- Must contain at least one lowercase letter, one uppercase letter, one digit, and one special character from the visible set that is not a letter or digit;\n- Must not contain the substring 'password' in any casing (e.g. Password, PASSWORD).\nReject anything else.",
      "regex": "/^(?!.*password)(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)(?=.*[^A-Za-z0-9])[!-~]{10,64}$/i"
    },
    {
      "slot": 3,
      "description": "api keys starting with 'pk_' then exactly 24 hex digits lowercase",
      "regex": "/^pk_[0-9a-f]{24}$/"
    },
    {
      "slot": 4,
      "description": "We need a passphrase policy for our internal tools: a passphrase must consist of at least four words, where a word is a sequence of ASCII letters (A–Z, a–z) only, separated by exactly one space. It must start and end with a word, and no leading or trailing spaces are allowed. Only the format is checked; dictionary strength is not evaluated.",
      "regex": "/^[A-Za-z]+(?: [A-Za-z]+){3,}$/"
    },
    {
      "slot": 5,
      "description": "We need to check that a password does not have the word password in it, in any case.",
      "regex": "/^(?!.*password).*$/i"
    }
  ]
}

