{
  "items": [
    {
      "slot": 1,
      "description": "A French postal code consists of exactly five digits. However, the first two digits correspond to the department number, which can be 01 to 95, or 2A or 2B for Corsica. Additionally, overseas departments and territories use three-digit department codes starting with 97 or 98, but for this validation we only consider metropolitan France and Corsica. So the postal code must start with either a two-digit number between 01 and 95, or the letters '2A' or '2B', followed by exactly three digits. No spaces or other characters are allowed.",
      "regex": "/^(?:0[1-9]|[1-8][0-9]|9[0-5]|2[AB])\\d{3}$/i"
    },
    {
      "slot": 2,
      "description": "A German IBAN (International Bank Account Number) has the following format: two uppercase letters 'DE' followed by two check digits (any two digits), then exactly 18 digits. The total length is 22 characters. No spaces or separators are allowed. Only the format is checked, not the validity of the check digits.",
      "regex": "/^DE\\d{20}$/"
    },
    {
      "slot": 3,
      "description": "In our e-commerce checkout, we need to validate UK postcodes for shipping addresses. A UK postcode consists of two parts: the outward code and the inward code, separated by a space. The outward code can be 2 to 4 characters: it starts with one or two uppercase letters (the area), optionally followed by one or two digits (the district), and may optionally have a letter after the digits (the sector). The inward code is always three characters: one digit followed by two uppercase letters. The space between the outward and inward codes is mandatory. The entire postcode must be uppercase.",
      "regex": "/^[A-Z]{1,2}\\d{1,2}[A-Z]? \\d[A-Z]{2}$/"
    },
    {
      "slot": 4,
      "description": "A credit card number must be exactly 16 digits. It may optionally be written in groups of four digits separated by a single space. The groups must be exactly four digits each, and there must be no leading or trailing spaces. So valid formats are either 16 consecutive digits, or four groups of four digits separated by single spaces.",
      "regex": "/^(?:\\d{4} ){3}\\d{4}$|^\\d{16}$/"
    },
    {
      "slot": 5,
      "description": "We need to accept credit card numbers in our payment form. The numbers are 16 digits long, but customers often type them with spaces every four digits. We want to allow that, but only if the spaces are exactly every four digits and the total number of digits is still 16. No other separators (like dashes) are allowed, and there should be no extra spaces at the beginning or end.",
      "regex": "/^(?:\\d{4} ){3}\\d{4}$|^\\d{16}$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "Validate an ISO 8601 duration string. The format is P followed by one or more components: optionally years (Y), months (M), days (D), then optionally a time part starting with T containing hours (H), minutes (M), and seconds (S). At least one component must be present. Each number is one or more digits. The time part must include at least one component if T is present.",
      "regex": "/^P(?=\\d|T\\d)(?:\\d+Y)?(?:\\d+M)?(?:\\d+D)?(?:T(?:\\d+H)?(?:\\d+M)?(?:\\d+S)?)?$/"
    },
    {
      "slot": 2,
      "description": "us dates mm/dd/yyyy or mm-dd-yyyy, separators must match, year 4 digits",
      "regex": "/^(\\d{2})\\/(\\d{2})\\/\\d{4}$|^(\\d{2})-(\\d{2})-\\d{4}$/"
    },
    {
      "slot": 3,
      "description": "iso 8601 duration like P3DT4H",
      "regex": "/^P(?=\\d|T\\d)(?:\\d+Y)?(?:\\d+M)?(?:\\d+D)?(?:T(?:\\d+H)?(?:\\d+M)?(?:\\d+S)?)?$/"
    },
    {
      "slot": 4,
      "description": "Match a three-letter English month abbreviation. It must be one of: Jan, Feb, Mar, Apr, May, Jun, Jul, Aug, Sep, Oct, Nov, Dec. The first letter is uppercase, the remaining two are lowercase.",
      "regex": "/^(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)$/"
    },
    {
      "slot": 5,
      "description": "month abbreviation with optional period",
      "regex": "/^(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\\.?$/"
