{
  "items": [
    {
      "slot": 1,
      "description": "Our authentication system uses JSON Web Tokens. A valid token consists of three parts separated by periods: the header, payload, and signature. Each part is a Base64URL-encoded string, which may contain letters (both uppercase and lowercase), digits, hyphens, and underscores. The parts must not be empty. Ensure the entire token matches this format.",
      "regex": "/^[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+$/"
    },
    {
      "slot": 2,
      "description": "We need to validate that a string is a JSON array containing only numbers (integers or decimals, possibly negative) and nothing else. The array must start with '[' and end with ']', and elements must be separated by commas. Whitespace is allowed between elements and brackets.",
      "regex": "/^\\[\\s*-?\\d+(?:\\.\\d+)?(?:\\s*,\\s*-?\\d+(?:\\.\\d+)?)*\\s*\\]$/"
    },
    {
      "slot": 3,
      "description": "Our configuration strings are a series of key=value pairs separated by ampersands. Keys must be alphanumeric and start with a letter. Values can be any characters except ampersand and equals sign. Each pair must have at least one character in the value. The whole string must not be empty and must not start or end with an ampersand.",
      "regex": "/^[A-Za-z][A-Za-z0-9]*=[^&=]+(?:&[A-Za-z][A-Za-z0-9]*=[^&=]+)*$/"
    },
    {
      "slot": 4,
      "description": "Match a simple XML-like tag pair where the opening and closing tag names are identical. The tag name must start with a letter or underscore and can contain letters, digits, hyphens, underscores, and periods. The content between tags can be any characters except '<' and '>', and may be empty.",
      "regex": "/^<([A-Za-z_][A-Za-z0-9_.-]*)>[^<>]*<\\/\\1>$/"
    },
    {
      "slot": 5,
      "description": "Match a string that is a valid Base64 encoding. It must consist of groups of four characters from A-Z, a-z, 0-9, +, and /, with the last group possibly padded with one or two equals signs. Empty strings are not allowed.",
      "regex": "/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/"
