{
  "items": [
    {
      "slot": 1,
      "description": "A longitude value in decimal degrees. The value must be a number between -180 and 180 inclusive. It may have an optional minus sign for negative values, and may include a decimal part separated by a dot. The integer part may have leading zeros. The decimal part, if present, must have at least one digit and may have up to six digits. The number must not exceed 180 in absolute value. Examples of valid: -180, 180, 0, 123.456, -0.000001. Invalid: 180.000001, -180.1, 200, 12.3456789 (too many decimal places), +90 (plus sign not allowed).",
      "regex": "/^(?:-?(?:180(?:\\.0{1,6})?|(?:\\d{1,2})(?:\\.\\d{1,6})?|(?:1[0-7]\\d)(?:\\.\\d{1,6})?))$/"
    },
