{
  "items": [
    {
      "slot": 1,
      "description": "common log format access log line with ip, ident, user, timestamp, request, status, bytes",
      "regex": "/^\\S+ \\S+ \\S+ \\[\\d{2}\\/[A-Za-z]{3}\\/\\d{4}:\\d{2}:\\d{2}:\\d{2} [+-]\\d{4}\\] \"[^\"]*\" \\d{3} \\d+$/"
    },
    {
      "slot": 2,
      "description": "Contains a duration of at least one second, written as a decimal number followed by 's', such as '1.2s' or '10s'.",
      "regex": "/\\b(?:\\d+(?:\\.\\d+)?|\\.\\d+)s\\b/"
    },
    {
      "slot": 3,
      "description": "log line beginning with level ERROR or WARN exactly and a space, but not the word ERRORLESS or WARNING",
      "regex": "/^(?:ERROR|WARN) /"
    },
    {
      "slot": 4,
      "description": "We need to parse lines where the level is written first, but only if it's a valid level (DEBUG, INFO, WARN, ERROR, or FATAL). The level must be followed by a space and then the message. Make sure it doesn't match words that just start with those letters, like 'INFORMATION'. This is for our log filtering system.",
      "regex": "/^(?:DEBUG|INFO|WARN|ERROR|FATAL) /"
    },
    {
      "slot": 5,
      "description": "line with a stack trace frame like at com.example.Foo.bar(Foo.java:123)",
      "regex": "/\\bat\\s+[\\w$.]+\\([\\w$]+\\.java:\\d+\\)/"
    }
  ]
}

