      "regex": "/^<([A-Za-z_][A-Za-z0-9_-]*)>[^<]*<\\/\\1>$/"
    },
    {
      "slot": 3,
      "description": "The string must be a JSON Web Token (JWT). Constraints:\n1. It consists of exactly three parts separated by dot (.) characters.\n2. Each part is a Base64URL-encoded string, i.e., it may contain the characters A-Z, a-z, 0-9, '-' (hyphen), and '_' (underscore), and no padding '=' characters are allowed.\n3. The first part (header) and second part (payload) must contain at least one character.\n4. The third part (signature) may be empty.\n5. There must be no leading or trailing whitespace or other characters.\n6. Only the format is checked; the encoded content and signature validity are not verified.",
      "regex": "/^[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]*$/"
    },
    {
      "slot": 4,
      "description": "A valid string is a standard Base64 encoding:\n- It consists only of the characters A-Z, a-z, 0-9, '+', and '/'.\n- Its length is a multiple of 4.\n- It may end with one or two padding '=' characters to make the length a multiple of 4; padding only appears at the end and only if the encoded data length would otherwise not be a multiple of 4.\n- An empty string is not a valid Base64 string.\n- The input must not contain any whitespace or line breaks.\n- The decoded content is not validated; only the encoded format is checked.",
      "regex": "/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/"
    },
    {
      "slot": 5,
      "description": "base64 string format only not empty no whitespace",
      "regex": "/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/"
    }
  ]
}

