    {
      "slot": 1,
      "description": "We need to flag user-submitted notes that contain at least one line beginning with a hash character, so they can be routed to the moderation queue.",
      "regex": "/^#/m"
    },
    {
      "slot": 2,
      "description": "any text with a blank line in it\n",
      "regex": "/^(?:.*\\n)*?\\n/m"
    },
    {
      "slot": 3,
      "description": "The input is valid if it consists of no more than three lines. Lines are separated by newline characters, and the whole input may end without a trailing newline.",
      "regex": "/^[^\\n]*(?:\\n[^\\n]*){0,2}$/"
    },
    {
      "slot": 4,
      "description": "We need to let users insert a paragraph break in their bio, so the text must contain at least one completely empty line between two non-empty lines.",
      "regex": "/\\n[ \\t]*\\n/"
    },
    {
      "slot": 5,
      "description": "The string must contain a comment block that starts with a line containing exactly three hyphens and ends with a later line containing exactly three hyphens, with arbitrary lines in between.",
      "regex": "/^---$[\\s\\S]*?^---$/m"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "A string that does not contain the substring 'admin' anywhere. The string can be empty or contain any other characters.",
      "regex": "/^(?:(?!admin)[\\s\\S])*$/"
    },
    {
      "slot": 2,
      "description": "We need to validate usernames for our internal system. They must not begin with the reserved prefix 'sys_'. Any other characters are allowed after that, but the username cannot be empty.",
      "regex": "/^(?!sys_).+$/"
    },
    {
      "slot": 3,
      "description": "A valid identifier is a non-empty sequence of alphanumeric characters and underscores, but it must not consist entirely of uppercase letters. Lowercase letters, digits, and underscores are allowed, but at least one character must be non-uppercase.",
      "regex": "/^(?![A-Z_]*$)[A-Za-z0-9_]+$/"
    },
    {
      "slot": 4,
      "description": "For our employee portal, each user has an ID that can contain letters, numbers, and underscores, but it cannot be all uppercase letters because that would conflict with department codes.",
      "regex": "/^(?![A-Z_]*$)[A-Za-z0-9_]+$/"
    },
    {
      "slot": 5,
      "description": "A file name that does not end with the extension '.tmp'. The file name can contain any characters, but the last four characters must not be '.tmp'.",
      "regex": "/^(?!.*\\.tmp$).+$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "We allow users to enter a package weight in either kilograms or grams on the shipping form. Only a non‑negative number with up to three decimal places is accepted, and the unit must be exactly kg or g (case‑insensitive). No signs, no spaces between the number and the unit, and a whole number must not include a trailing decimal point. Values like 0 kg or 0.5 g are fine, but amounts with a leading plus sign, without a unit, or with more than three decimals are rejected.",
      "regex": "/^(?:0|[1-9]\\d*)(?:\\.\\d{1,3})?(?:kg|g)$/i"
    },
    {
      "slot": 2,
      "description": "screen resolution like 1920x1080, width first, height second, both whole numbers with 1 to 5 digits, lowercase x as separator, no spaces",
      "regex": "/^\\d{1,5}x\\d{1,5}$/"
    },
    {
      "slot": 3,
      "description": "Latitude in decimal degrees. Rules:\n- Must start with an optional minus sign followed by a number.\n- Integer part: 0 to 90.\n- If the integer part is 0 or 90, the fractional part (if present) must be all zeros (e.g., 0.0, 90.000, -90.00 are valid; 0.1 and 90.1 are not).\n- If the integer part is between 1 and 89 inclusive, an optional fractional part with up to 6 decimal places is allowed.\n- The minus sign is allowed only if the absolute value is less than or equal to 90.\n- No leading zeros in the integer part unless the integer part is exactly 0.\n- No plus sign.",
      "regex": "/^-?(?:90(?:\\.0{1,6})?|(?:[1-8]\\d|0)(?:\\.\\d{1,6})?)$/"
    },
    {
      "slot": 4,
      "description": "A longitude in decimal degrees. It may optionally begin with a minus sign, and the integer part must be between 0 and 180 inclusive with no leading zeros unless the value is exactly zero. If the absolute integer part is 180, any fractional part must be all zeros; otherwise up to six decimal places are allowed.",
      "regex": "/^-?(?:180(?:\\.0{1,6})?|(?:[1-9]\\d?|0)(?:\\.\\d{1,6})?)$/"
    },
    {
      "slot": 5,
      "description": "File size: a positive integer (no leading zeros) followed by exactly one space and one of KB, MB, or GB. The unit must be uppercase.",
      "regex": "/^[1-9]\\d* (?:KB|MB|GB)$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "Validate a US dollar amount. The amount must start with the dollar sign ($), followed by an integer part with no leading zeros, using commas as thousands separators. The integer part may be a single digit or a group of 1–3 digits followed by zero or more groups of a comma and exactly three digits. A decimal part is optional; if present, it must be a period followed by exactly two digits.",
      "regex": "/^\\$(0|[1-9]\\d{0,2}(,\\d{3})*)(\\.\\d{2})?$/"
    },
    {
      "slot": 2,
      "description": "Validate a negative amount in accounting format. The amount must be enclosed in parentheses, starting with an opening parenthesis and ending with a closing parenthesis. Inside, there must be a dollar sign ($), followed by an integer part with no leading zeros, using commas as thousands separators. The integer part may be a single digit or a group of 1–3 digits followed by zero or more groups of a comma and exactly three digits. A decimal part is optional; if present, it must be a period followed by exactly two digits.",
      "regex": "/^\\(\\$(0|[1-9]\\d{0,2}(,\\d{3})*)(\\.\\d{2})?\\)$/"
    },
    {
      "slot": 3,
      "description": "Match a price that is written with exactly two decimal places, which may be preceded by an optional dollar sign and an integer part that can include commas as thousands separators.",
      "regex": "/^\\$?\\d{1,3}(,\\d{3})*\\.\\d{2}$/"
    },
    {
      "slot": 4,
      "description": "japanese yen amount no decimals no commas",
      "regex": "/^¥\\d+$/"
    },
    {
      "slot": 5,
      "description": "A valid US dollar amount consists of an optional dollar sign ($) followed by an integer part with no leading zeros, using commas as thousands separators if needed. The integer part may be a single digit or a group of 1–3 digits followed by zero or more groups of a comma and exactly three digits. A decimal part is optional: if present, it must be a period followed by exactly two digits.",
      "regex": "/^\\$?(0|[1-9]\\d{0,2}(,\\d{3})*)(\\.\\d{2})?$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "A valid HTTP status line must follow this format: it starts with 'HTTP/', then a version number consisting of one digit, a dot, and one digit, then a single space, then a three-digit status code that must be either 4xx or 5xx (i.e., first digit 4 or 5, followed by two digits), then a single space, then a reason phrase consisting of zero or more characters (any characters except newline). The line must not contain any newline characters. The entire string must match exactly from start to end.",
      "regex": "/^HTTP\\/[0-9]\\.[0-9] [45][0-9]{2} [^\\n]*$/"
    },
    {
      "slot": 2,
      "description": "We need to detect log lines that contain a typical stack trace frame from a Java or similar runtime, which starts with optional whitespace, followed by the word 'at', then whitespace, then a fully qualified method name (like com.example.Class.method), followed by a file name in parentheses with a line number (e.g., (File.java:123)). The line may have other content before or after this frame, but the frame itself must be present.",
      "regex": "/\\s*at\\s+[\\w.$]+\\([\\w.]+\\.java:\\d+\\)/"
    },
    {
      "slot": 3,
      "description": "log line with duration > 1s",
      "regex": "/\\b(?:[2-9]\\d*|1\\d+)(?:\\.\\d+)?s\\b/"
    },
    {
      "slot": 4,
      "description": "log line starting with ERROR or WARN level, case insensitive, followed by colon and space, then any message that must not contain a newline",
      "regex": "/^(?:ERROR|WARN): [^\\n]*$/i"
    },
    {
      "slot": 5,
      "description": "http status line with 4xx or 5xx code",
      "regex": "/^HTTP\\/\\d\\.\\d [45]\\d{2} .*$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "A Windows absolute path starts with a drive letter followed by a colon and a backslash. After that, it consists of one or more path segments separated by backslashes. Each segment must be non-empty and cannot contain any of the characters < > : \" / \\ | ? *.",
      "regex": "/^[A-Za-z]:\\\\(?:[^<>:\"\\/\\\\|?*]+\\\\)*[^<>:\"\\/\\\\|?*]+$/"
    },
