      "slot": 2,
      "description": "An image file name must end with a dot followed by one of these extensions, case-insensitive: jpg, jpeg, png, gif, or bmp. The part before the dot must not be empty and must not contain a dot.",
      "regex": "/^[^.]+\.(?:jpe?g|png|gif|bmp)$/i"
    },
    {
      "slot": 3,
      "description": "A Windows absolute path with a drive letter: it starts with a single letter, then a colon, then a backslash. The remainder is a sequence of path segments separated by backslashes, where each segment is at least one character long and may not include the characters < > : \" / \\ | ? *.",
      "regex": "/^[A-Za-z]:\\\\(?:[^<>:\"\\/\\\\|?*]+\\\\)*[^<>:\"\\/\\\\|?*]+$/"
    },
    {
      "slot": 4,
      "description": "We need to validate Unix absolute paths in our configuration loader. A valid path must start with a forward slash, and then contain one or more path components separated by single forward slashes. Each component must consist of one or more characters that are not forward slashes, and must not be the special components '.' or '..'. The path must not end with a trailing slash unless it is exactly the root slash.",
      "regex": "/^\\/(?:[^\\/]+\\/)*[^\\/]+$|^\\/$/"
    },
    {
      "slot": 5,
      "description": "hidden dotfile name. It must start with a dot, followed by a non-empty sequence of characters that are not slash or backslash.",
