      "regex": "/^((?:\\*)|(?:(?:[0-5]?\\d)(?:-(?:[0-5]?\\d))?)(?:,(?:(?:[0-5]?\\d)(?:-(?:[0-5]?\\d))?))* )((?:\\*)|(?:(?:[01]?\\d|2[0-3])(?:-(?:[01]?\\d|2[0-3]))?)(?:,(?:(?:[01]?\\d|2[0-3])(?:-(?:[01]?\\d|2[0-3]))?))* )((?:\\*)|(?:(?:[1-9]|[12]\\d|3[01])(?:-(?:[1-9]|[12]\\d|3[01]))?)(?:,(?:(?:[1-9]|[12]\\d|3[01])(?:-(?:[1-9]|[12]\\d|3[01]))?))* )((?:\\*)|(?:(?:[1-9]|1[0-2])(?:-(?:[1-9]|1[0-2]))?)(?:,(?:(?:[1-9]|1[0-2])(?:-(?:[1-9]|1[0-2]))?))* )((?:\\*)|(?:(?:[0-7])(?:-(?:[0-7]))?)(?:,(?:(?:[0-7])(?:-(?:[0-7]))?))*)$/"
    },
    {
      "slot": 4,
      "description": "Validate a semantic PR title that follows the pattern: <type>(<scope>): <subject> [<ticket>]. The type must be one of feat, fix, docs, style, refactor, perf, test, build, ci, chore, or revert. The scope is optional and consists of alphanumeric characters, hyphens, and underscores, enclosed in parentheses immediately after the type. A colon and a single space follow the type/scope. The subject must be at least one non-whitespace character, can contain spaces, and must not be empty or consist only of whitespace. The ticket key is optional and, if present, must be enclosed in square brackets at the end of the string. The ticket key consists of two to ten uppercase letters, a hyphen, and one or more digits. The entire string should not have leading or trailing whitespace.",
      "regex": "/^(feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert)(?:\\([a-zA-Z0-9_-]+\\))?: [^\\s].*?(?:\\s[A-Z]{2,10}-\\d+)?$/"
