      "description": "Our security policy says a user's password must be between 12 and 64 characters and must not contain the consecutive letters 'password' in any casing, as that would be too easy to guess. Only printable ASCII characters are allowed; no spaces or control characters.",
      "regex": "/^(?=.*password)(?!.*password).*$/i"
    },
    {
      "slot": 2,
      "description": "password with no whitespace and no triple repeated character",
      "regex": "/^(?!.*(.)\\1{2})\\S+$/"
    },
    {
      "slot": 3,
      "description": "The password must satisfy all of the following:\n- Length between 8 and 128 characters.\n- Must not contain any whitespace characters (spaces, tabs, newlines, etc.).\n- Must not contain the same character three times in a row (e.g., 'aaa', '!!!', '111').",
      "regex": "/^(?!.*(.)\\1{2})\\S{8,128}$/"
    },
    {
      "slot": 4,
      "description": "API key format:\n- Must start with the prefix 'sk_'.\n- After the prefix, there must be exactly 32 characters from the set [A-Za-z0-9].\n- No other characters or separators are allowed.",
      "regex": "/^sk_[A-Za-z0-9]{32}$/"
    },
    {
      "slot": 5,
      "description": "When users set a password, we need to ensure it does not contain the word 'password' in any casing, as that is a common weak choice.",
      "regex": "/^(?!.*password).*$/i"
    }
  ]
}

