{
  "items": [
    {
      "slot": 1,
      "description": "git tag like v1.2 or v1.2.3: must start with v, then a major version number without leading zeros (0 or non-zero digit followed by more digits), then a dot, then a minor version number without leading zeros, optionally a dot and a patch version number without leading zeros. no pre-release or build metadata.",
      "regex": "/^v(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:\\.(0|[1-9]\\d*))?$/"
    },
    {
      "slot": 2,
      "description": "semantic version: major.minor.patch, each a non-negative integer without leading zeros. optionally followed by a pre-release identifier: a hyphen, then one or more dot-separated identifiers. each identifier is either numeric (no leading zeros) or alphanumeric with at least one letter (ascii letters, digits, hyphens allowed). optionally followed by build metadata: a plus sign, then one or more dot-separated identifiers, each consisting of ascii alphanumerics and hyphens, at least one character.",
      "regex": "/^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-((?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\\.(?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\\+([0-9a-zA-Z-]+(?:\\.[0-9a-zA-Z-]+)*))?$/"
    },
    {
      "slot": 3,
      "description": "we need to validate npm version range strings in our dependency checker. the range must start with either a caret or a tilde, followed by a version number in the form major.minor.patch where each part is a non-negative integer without leading zeros. no extra spaces or characters.",
      "regex": "/^[~^](0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)$/"
    },
    {
      "slot": 4,
      "description": "calendar version in year.month format: exactly four digits for the year, a dot, then exactly two digits for the month from 01 to 12.",
      "regex": "/^\\d{4}\\.(0[1-9]|1[0-2])$/"
    },
    {
      "slot": 5,
      "description": "we need to validate version strings for our products that follow a calendar versioning scheme. the version must be in the format YYYY.MM where YYYY is a four-digit year (any year) and MM is a two-digit month from 01 to 12. optionally, a patch number can be appended as a dot followed by one or more digits. no other characters allowed.",
      "regex": "/^\\d{4}\\.(0[1-9]|1[0-2])(?:\\.\\d+)?$/"
    }
  ]
}

