    {
      "slot": 1,
      "description": "In our backend logs, we need to distinguish absolute Unix paths from relative ones. An absolute Unix path always starts with a forward slash and has no whitespace characters and no colon. It can be just the root slash or have additional path segments separated by single slashes. No segment may be empty.",
      "regex": "/^\\/(?:[^\\s/:]+(?:\\/[^\\s/:]+)*)?$/"
    },
    {
      "slot": 2,
      "description": "For a cross-platform file upload feature, we need to validate file names that users provide. A valid file name must not be empty, must not contain any of these characters: forward slash, backslash, colon, asterisk, question mark, double quote, less-than, greater-than, or pipe. It also cannot start or end with a whitespace character, and cannot contain any control characters (ASCII codes 0-31). It can contain any other printable character, including spaces, dots, and dashes.",
      "regex": "/^(?=[^\\/\\\\:*?\"<>|]*[^\\s\\/\\\\:*?\"<>|])[^\\x00-\\x1f\\/\\\\:*?\"<>|]+$/"
    },
    {
      "slot": 3,
      "description": "Match a Unix absolute path. The path starts with a forward slash. It may optionally have one or more segments. Each segment consists of one or more characters that are not slashes, whitespace, colons, or the characters '.' or '-'. The segments are separated by single forward slashes, and the path does not end with a slash unless it is just the root.",
      "regex": "/^\\/(?:[^\\s\\/:.\\-]+(?:\\/[^\\s\\/:.\\-]+)*)?$/"
    },
    {
      "slot": 4,
      "description": "A Windows path with a drive letter must satisfy all of the following:\n- Begins with a single uppercase or lowercase ASCII letter followed by a colon.\n- After the colon, either a backslash or a forward slash must appear.\n- Then, zero or more segments separated by either backslash or forward slash.\n- Each segment must consist of one or more characters that are not colon, asterisk, question mark, double quote, less-than, greater-than, pipe, backslash, forward slash, or control characters (ASCII 0-31).\n- The path must not end with a backslash or forward slash, unless it is just the drive root (e.g., C:\\).",
      "regex": "/^[A-Za-z]:[\\\\\\/](?:[^\\\\\\/:*?\"<>|\\x00-\\x1f]+(?:[\\\\\\/][^\\\\\\/:*?\"<>|\\x00-\\x1f]+)*)?$/"
    },
    {
      "slot": 5,
      "description": "When users upload attachments, we need to check that the file name part is safe. The file name must be between 1 and 255 characters long. It cannot contain any of these characters: forward slash, backslash, colon, semicolon, asterisk, question mark, double quote, less-than, greater-than, pipe, or newline. It also cannot consist solely of dots or spaces; it must contain at least one letter, digit, underscore, hyphen, or other non-forbidden, non-dot, non-space character. Spaces and dots are allowed elsewhere. The file name must not start or end with a space or a dot. Control characters (ASCII 0-31) are not allowed.",
      "regex": "/^(?=[^\\/\\\\:;*?\"<>|\\x00-\\x1f]{1,255}$)(?![\\.\\s])(?!.*[\\.\\s]$)(?=.*[^\\s.\\/\\\\:;*?\"<>|\\x00-\\x1f])[^\\/\\\\:;*?\"<>|\\x00-\\x1f]+$/"
    }
  ]
}

