      "slot": 2,
      "description": "A string is a valid IPv4 CIDR notation if it consists of an IPv4 address in dotted-decimal form (four octets, each a number from 0 to 255 with no leading zeros) followed by a slash and a prefix length from 0 to 32. The prefix length must be a number without leading zeros, except that 0 itself is allowed.",
      "regex": "/^(?:(?:25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])\\.){3}(?:25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])\\/(?:3[0-2]|2[0-9]|1[0-9]|[0-9])$/"
    },
    {
      "slot": 3,
      "description": "We need to validate the hostname field in our server configuration form. The hostname must follow RFC 1123: it can consist of labels separated by dots. Each label can contain letters (case-insensitive), digits, and hyphens, but cannot start or end with a hyphen. Labels must be 1 to 63 characters long. The entire hostname must be at most 253 characters and must not end with a trailing dot.",
      "regex": "/^(?=.{1,253}\\.?$)(?!-)[A-Za-z0-9-]{1,63}(?<!-)(?:\\.(?!-)[A-Za-z0-9-]{1,63}(?<!-))*\\.?$/"
    },
    {
      "slot": 4,
      "description": "IPv4 CIDR block",
      "regex": "/^(?:(?:25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])\\.){3}(?:25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])\\/(?:3[0-2]|2[0-9]|1[0-9]|[0-9])$/"
    },
    {
      "slot": 5,
      "description": "A string is a valid private IPv4 address if it is a dotted-decimal IPv4 address where the first octet is 10, or the first octet is 172 and the second octet is between 16 and 31 inclusive, or the first two octets are exactly 192.168. Each octet must be a number from 0 to 255 with no leading zeros. Only the format is checked.",
      "regex": "/^(?:10\\.(?:25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])\\.(?:25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])\\.(?:25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])|172\\.(?:1[6-9]|2[0-9]|3[01])\\.(?:25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])\\.(?:25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])|192\\.168\\.(?:25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])\\.(?:25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9]))$/"
    }
  ]
}

