{
  "items": [
    {
      "slot": 1,
      "description": "We need to validate a username field in our signup form. The username must be a single word consisting only of lowercase letters (a-z), and it must not be any of our reserved system words: admin, root, user, guest, or test.",
      "regex": "/^(?!(?:admin|root|user|guest|test)$)[a-z]+$/"
    },
    {
      "slot": 2,
      "description": "Match a file name that does not end with the .exe extension. The file name may contain any characters except slashes and backslashes, and it must be at least one character long.",
      "regex": "/^(?!.*\\.exe$)[^\\/\\\\]+$/"
    },
    {
      "slot": 3,
      "description": "Validate a word that is not one of the following reserved keywords: class, function, return, var, let, const, if, else, for, while. The word must consist entirely of letters (a-z, A-Z) and must not be any of these reserved words.",
      "regex": "/^(?!(?:class|function|return|var|let|const|if|else|for|while)$)[A-Za-z]+$/"
    },
    {
      "slot": 4,
      "description": "Match a string that does not contain the substring 'error'. The string can contain any characters.",
      "regex": "/^(?!.*error).*$/"
    },
    {
      "slot": 5,
      "description": "In our inventory system, we need to accept numeric item IDs that do not end with the digit 0. The ID must be a non-empty sequence of digits (0-9) that does not end with 0.",
      "regex": "/^\\d*[1-9]$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "We need to validate user comments in a forum. A comment must be at most three lines. Each line can contain any characters except newline, but no line may be empty. The entire comment must not be empty. Lines are separated by standard line breaks (\\n, \\r, or \\r\\n).",
      "regex": "/^(?:(?!\\s*$)[^\\r\\n]+)(?:\\r?\\n(?!\\s*$)[^\\r\\n]+){0,2}$/"
    },
    {
      "slot": 2,
      "description": "Our markdown editor should only accept documents where at least one line starts with a hash symbol (#) followed immediately by a non-space character. The document can have any number of lines, and lines are separated by standard line breaks.",
      "regex": "/^(?=.*^#[^\\s\\r\\n].*$)[\\s\\S]*$/m"
    },
    {
      "slot": 3,
      "description": "Match a text block that contains at most three lines. Each line may be empty, and lines are separated by newline characters.",
      "regex": "/^(?:[^\\r\\n]*(?:\\r?\\n|$)){0,3}$/"
    },
    {
      "slot": 4,
      "description": "A bio for a social profile can have up to three lines. Each line can contain any characters except newline, but lines cannot be empty. The whole bio cannot be empty. Lines are separated by \\n, \\r, or \\r\\n.",
      "regex": "/^(?!$)(?!\\s*$)[^\\r\\n]+(?:\\r?\\n(?!\\s*$)[^\\r\\n]+){0,2}$/"
    },
    {
      "slot": 5,
      "description": "Match a text block that contains at least one blank line (a line that is empty or contains only spaces and tabs). The blank line must be between two lines that may contain any characters. The text must have at least three lines in total to have a blank line in the middle.",
      "regex": "/^(?:[^\\r\\n]*\\r?\\n){1,}[ \\t]*\\r?\\n(?:.*\\r?\\n)*[^\\r\\n]*$/m"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "iso 8601 date with hyphens and basic format",
      "regex": "/^\\d{4}-\\d{2}-\\d{2}$/"
    },
    {
      "slot": 2,
      "description": "In our scheduling system, users pick a month from a dropdown. The dropdown displays English three-letter month abbreviations, always capitalized: Jan, Feb, Mar, Apr, May, Jun, Jul, Aug, Sep, Oct, Nov, Dec. However, we want to validate that the stored value matches one of these exactly, with no extra characters or different casing.",
      "regex": "/^(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)$/"
    },
    {
      "slot": 3,
      "description": "A string represents a time in 24-hour format, with hours from 00 to 23, minutes from 00 to 59, and an optional seconds part from 00 to 59. If seconds are present, they must be preceded by a colon. The time must be exactly in this format with no extra characters.",
      "regex": "/^([01]\\d|2[0-3]):[0-5]\\d(:[0-5]\\d)?$/"
    },
    {
      "slot": 4,
      "description": "A valid date in ISO 8601 calendar date format consists of four digits for the year, a hyphen, two digits for the month from 01 to 12, a hyphen, and two digits for the day from 01 to 31. The entire string must match this format exactly.",
      "regex": "/^\\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\\d|3[01])$/"
    },
    {
      "slot": 5,
      "description": "A string must be a valid ISO 8601 calendar date in extended format: exactly four digits for the year, followed by a hyphen, then two digits for the month, followed by a hyphen, then two digits for the day. The day must be between 01 and 31, and the month between 01 and 12. No other characters are allowed.",
      "regex": "/^\\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\\d|3[01])$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "A string is a valid even integer if it consists only of an optional minus sign followed by one or more decimal digits, and the final digit is 0, 2, 4, 6, or 8. No leading zeros are allowed unless the number is exactly 0.",
      "regex": "/^-?(?:0|[1-9][0-9]*[02468]|[1-9][0-9]*0)$/"
    },
    {
      "slot": 2,
      "description": "Match an even integer. It may be negative, and it must not have leading zeros unless it is zero.",
      "regex": "/^-?(?:0|[1-9][0-9]*[02468])$/"
    },
    {
      "slot": 3,
      "description": "Match a positive integer with no leading zeros. The number must be strictly greater than zero and the first digit cannot be zero.",
      "regex": "/^[1-9][0-9]*$/"
    },
    {
      "slot": 4,
      "description": "We need to validate a quantity field in an order form. It must be a positive whole number (no decimal point, no sign) and cannot have leading zeros.",
      "regex": "/^[1-9][0-9]*$/"
    },
    {
      "slot": 5,
      "description": "Match an octet value from 0 to 255 inclusive. Leading zeros are not allowed unless the value is exactly 0.",
