{
  "items": [
    {
      "slot": 1,
      "description": "A relative URL that must start with a slash. The rest may be path segments separated by slashes, and it may end with a query string that begins with a question mark. Each path segment can only contain letters, digits, hyphens, underscores, dots, or percent-encoded characters (a percent sign followed by two hexadecimal digits).",
      "regex": "/^\\/(?:[A-Za-z0-9\\-._~]|%[0-9A-Fa-f]{2})*(?:\\/(?:[A-Za-z0-9\\-._~]|%[0-9A-Fa-f]{2})*)*(?:\\?(?:[A-Za-z0-9\\-._~]|%[0-9A-Fa-f]{2})*)?$/"
    },
    {
      "slot": 2,
      "description": "We need to detect if a chunk of HTML contains an opening anchor tag, possibly with attributes, used for link validation in our CMS. The tag must start with '<a', followed by at least one whitespace character if attributes are present, then any attributes (letters, digits, hyphens, equals, quotes, slashes, spaces, etc.), and end with '>'. It should not match '<area>' or other tags starting with 'a'.",
      "regex": "/<a\\s[^>]*>/"
    },
    {
      "slot": 3,
      "description": "web path starting with slash, no spaces, no query or fragment",
      "regex": "/^\\/[A-Za-z0-9\\-._~!$&'()*+,;=:@\\/]*$/"
    },
