}

{
  "items": [
    {
      "slot": 1,
      "description": "Phone number with an optional country code. The country code, if present, is a plus sign followed by one to three digits. The national number is exactly ten digits.",
      "regex": "/^(?:\\+\\d{1,3})?\\d{10}$/"
    },
    {
      "slot": 2,
      "description": "French mobile phone number: starts with 0 or +33, followed by 9 digits, with the first digit after the prefix being 6 or 7. The digits can be separated by spaces or hyphens in groups of two, but the total digit count must be 10 (or 9 after +33).",
      "regex": "/^(?:0|\\+33\\s?)[67](?:[\\s-]?\\d{2}){4}$/"
    },
    {
      "slot": 3,
      "description": "French mobile phone number. Must start with 0 or +33. The national significant number is 9 digits, starting with 6 or 7. Digits may be separated by single spaces or hyphens, but must be in groups of two (except possibly the first digit after the prefix).",
      "regex": "/^(?:0|\\+33)[\\s-]?[67](?:[\\s-]?\\d{2}){4}$/"
    },
    {
      "slot": 4,
      "description": "E.164 international phone number: starts with a plus sign, followed by a country code (1 to 3 digits, first digit 1-9), then the national number (up to 15 digits total). No spaces or other separators.",
      "regex": "/^\\+[1-9]\\d{1,2}\\d{1,12}$/"
    },
    {
      "slot": 5,
      "description": "North American phone number: area code and central office code must start with 2-9. Subscriber number can be any 7 digits. Optional formatting: area code may be enclosed in parentheses, and groups may be separated by spaces, hyphens, or dots. The number may optionally start with +1 or 1 followed by space, hyphen, or dot.",
      "regex": "/^(?:\\+?1[\\s.-]?)?(?:\\([2-9]\\d{2}\\)|[2-9]\\d{2})[\\s.-]?[2-9]\\d{2}[\\s.-]?\\d{4}$/"
    }
  ]
}

