{
  "items": [
    {
      "slot": 1,
      "description": "A Windows path must start with a drive letter (A-Z, case-insensitive) followed by a colon. It then consists of one or more path components, each beginning with a backslash. Every component is a sequence of one or more characters that are not backslashes, colons, asterisks, question marks, double quotes, angle brackets, or pipe characters. Each component must be at least one character long. The path ends after the last component.",
      "regex": "/^[A-Za-z]:\\\\[^\\\\:*?\"<>|]+(?:\\\\[^\\\\:*?\"<>|]+)*$/"
    },
    {
      "slot": 2,
      "description": "An image file name is made of a base name and an extension separated by a dot. The base name must be non-empty and may contain only letters, digits, underscores, hyphens, and spaces. The extension must be one of: jpg, jpeg, png, gif, bmp, webp, tif, tiff, svg. The extension is matched case-insensitively. The file name must not contain any other characters or additional dots.",
      "regex": "/^[A-Za-z0-9_\\- ]+\\.(?:jpe?g|png|gif|bmp|webp|tiff?|svg)$/i"
    },
    {
      "slot": 3,
      "description": "Our system only allows file names that are safe on all platforms. A valid file name must not contain any of these characters: backslash, forward slash, colon, asterisk, question mark, double quote, less-than, greater-than, or pipe. Control characters (ASCII 0-31) are also forbidden. The name must have at least one character and must not be exactly '.' or '..'. It cannot start or end with a space or a dot. Names that are only spaces are not allowed. No other restrictions apply.",
      "regex": "/^(?!\\.\\.?$)(?!.*[\\\\/:*?\"<>|\\x00-\\x1F])[^\\x00-\\x1F\\\\/:*?\"<>|](?:[^\\x00-\\x1F\\\\/:*?\"<>|]*[^\\x00-\\x1F\\\\/:*?\"<>|. ])?$/"
    },
    {
      "slot": 4,
      "description": "Match an image file name ending in .jpg, .jpeg, .png, .gif, .bmp, .webp, .tif, .tiff, or .svg (case-insensitive). The base name can be anything except a dot.",
      "regex": "/^[^.]+(?:\\.[^.]+)*\\.(?:jpe?g|png|gif|bmp|webp|tiff?|svg)$/i"
    },
    {
      "slot": 5,
      "description": "A Unix absolute path must start with a forward slash. It may optionally consist of a sequence of path components, each beginning with a forward slash and followed by one or more characters that are not forward slashes. The special cases of a single root slash or a path ending with a trailing slash are allowed, but no two consecutive slashes are permitted except for the root itself.",
      "regex": "/^\\/(?:[^/]+(?:\\/[^/]+)*)?\\/?$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "Match a semantic version number, optionally followed by a pre-release tag and/or build metadata. Core version is three dot-separated non-negative integers without leading zeros unless the number is exactly zero. Pre-release starts with a hyphen and consists of at least one identifier, each identifier being either a numeric identifier with the same no-leading-zero rule or an alphanumeric identifier containing at least one non-digit. Build metadata starts with a plus sign and consists of at least one dot-separated alphanumeric identifier, where an identifier may contain only digits.",
      "regex": "/^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-((?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\\.(?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\\+([0-9a-zA-Z-]+(?:\\.[0-9a-zA-Z-]+)*))?$/"
    },
    {
      "slot": 2,
      "description": "semantic version major minor patch no leading zeros",
      "regex": "/^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)$/"
    },
    {
      "slot": 3,
      "description": "When a customer enters a version requirement in the package manager configuration, we accept either a caret or a tilde followed immediately by a full three-part semantic version. The core version numbers must not have leading zeros unless the number is zero. No pre-release or build metadata is allowed.",
      "regex": "/^[~^](0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)$/"
    },
    {
      "slot": 4,
      "description": "Accept a caret or tilde version range, optionally followed by a hyphen and an upper bound separated by a single space. The upper bound may be either a full version or a partial version consisting of major only or major and minor. All present components must be non-negative integers without leading zeros unless the number is zero. Whitespace is not permitted anywhere else.",
      "regex": "/^[~^](0|[1-9]\\d*)(?:\\.(0|[1-9]\\d*))?(?:\\.(0|[1-9]\\d*))?(?: - (0|[1-9]\\d*)(?:\\.(0|[1-9]\\d*))?(?:\\.(0|[1-9]\\d*))?)?$/"
    },
    {
      "slot": 5,
      "description": "Exact semantic version format: three dot-separated components (major, minor, patch). Each component is a non-negative integer with no leading zeros unless the value is exactly 0. No pre-release or build metadata allowed.",
      "regex": "/^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)$/"
    }
  ]
}

