      "description": "The input is a string that is wrapped in matching single quotes or matching double quotes. The content between the quotes can be any characters except the quote character itself, and it can be empty.",
      "regex": "/^(?:'[^']*'|\"[^\"]*\")$/"
    },
    {
      "slot": 5,
      "description": "string wrapped in matching quotes",
      "regex": "/^(?:'[^']*'|\"[^\"]*\")$/"
    }
  ]
}

{
  "items": [
