      "description": "The text must be a block that begins with a line containing exactly \"BEGIN\", ends with a line containing exactly \"END\", and has at least one line in between. No other lines are allowed before or after, and the markers are case-sensitive.",
      "regex": "/^BEGIN\\n(?:.*\\n)*.*\\nEND$/"
    },
