    {
      "slot": 3,
      "description": "A text can have at most three lines. Each line must contain only word characters (letters, digits, or underscores) and may be empty. Line separators are newline characters, and no trailing newline is allowed unless it is followed by an empty line? Actually, no trailing newline at all.",
      "regex": "/^\\w*(?:\\n\\w*){0,2}$/"
    },
    {
      "slot": 4,
      "description": "A field in our app should accept a series of lines, each of which is a plain integer, either positive or negative, with no spaces. The text may have one or more such lines.",
      "regex": "/^-?\\d+(?:\\n-?\\d+)*$/"
    },
    {
      "slot": 5,
      "description": "The input is a multiline text. It is valid if at least one line (a line is any substring between newline characters or the start/end of the string) starts with a hash symbol (#). Other lines can be anything.",
      "regex": "/^.*(?:\\n|^)#.*$/m"
    }
  ]
}

{
