}

{
  "items": [
    {
      "slot": 1,
      "description": "Validate a Python version specifier. Rules: optional whitespace; then one of the operators ~=, ==, !=, <=, >=, <, >; no whitespace is allowed between the operator and the version; the version is a release segment (one or more dot-separated non-negative integers, each without leading zeros unless the number is exactly 0), optionally followed by a pre-release segment, a post-release segment, a development-release segment, and a local-version segment in that order: the pre-release segment is a hyphen followed by one of a, b, c, rc, alpha, beta, pre, preview, optionally followed by a dot and a non-negative integer (no leading zeros unless zero); the post-release segment is a hyphen followed by one of post, rev, r, optionally followed by a dot and a non-negative integer (no leading zeros unless zero); the development-release segment is a dot followed by dev and a non-negative integer (no leading zeros unless zero); the local-version segment is a plus sign followed by one to four dot-separated identifiers, each identifier consisting of ASCII alphanumeric characters and/or hyphens. Whitespace at the end is optional.",
      "regex": "/^\\s*(?:~=|==|!=|<=|>=|<>|<|>)\\s*[0-9]+(?:\\.[0-9]+)*(?:-(?:a|b|c|rc|alpha|beta|pre|preview)(?:\\.[0-9]+)?)?(?:-(?:post|rev|r)(?:\\.[0-9]+)?)?(?:\\.dev[0-9]+)?(?:\\+[a-zA-Z0-9-]+(?:\\.[a-zA-Z0-9-]+){0,3})?\\s*$/i"
    },
    {
      "slot": 2,
      "description": "Match a calendar version string. Rules: exactly 4 digits for the year, then a dot, then exactly 2 digits for the month (01 to 12), then a dot, then exactly 2 digits for the day (01 to 31). The entire string must match.",
      "regex": "/^\\d{4}\\.(?:0[1-9]|1[0-2])\\.(?:0[1-9]|[12][0-9]|3[01])$/"
    },
    {
      "slot": 3,
      "description": "A calendar version is a four-digit year, a dot, a two-digit month from 01 to 12, a dot, and a two-digit day from 01 to 31.",
      "regex": "/^\\d{4}\\.(?:0[1-9]|1[0-2])\\.(?:0[1-9]|[12][0-9]|3[01])$/"
    },
    {
      "slot": 4,
      "description": "Validate an npm version range with a caret or tilde. Format: optional whitespace, then a caret (^) or tilde (~), then an optional whitespace, then a version number consisting of dot-separated numeric segments (only digits, no leading zeros). The version number must have at least one segment (e.g., 1). Up to three segments are allowed (major, minor, patch). Optional whitespace at the end.",
      "regex": "/^\\s*[~^]\\s*\\d+(?:\\.\\d+){0,2}\\s*$/"
    },
    {
      "slot": 5,
      "description": "Validate a semantic version string. Rules: a version number is one or more dot-separated numeric identifiers, each without leading zeros unless the number is exactly 0; optionally followed by a hyphen and a pre-release part, which is one or more dot-separated identifiers, each consisting of ASCII alphanumeric characters and hyphens, and a numeric identifier in the pre-release part must not have leading zeros; optionally followed by a plus sign and a build metadata part, which is one or more dot-separated identifiers, each consisting of ASCII alphanumeric characters and hyphens. The entire string must match.",
      "regex": "/^(?:0|[1-9]\\d*)(?:\\.(?:0|[1-9]\\d*))*(?:-(?:[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*))?(?:\\+[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?$/"
    }
  ]
}

{
