{
  "items": [
    {
      "slot": 1,
      "description": "Match a latitude as a decimal number between -90 and 90 inclusive. An optional minus sign is allowed. The integer part is either a single digit or two digits where the first is 1 through 9. An optional fractional part may follow a decimal point, requiring at least one digit after the point.",
      "regex": "/^-?(?:\\d|\\d{2}(?:\\.\\d+)?)$|^-?(?:[1-8]\\d|\\d)(?:\\.\\d+)?$/"
    },
    {
      "slot": 2,
      "description": "degrees minutes seconds coords like 51° 30' 26\" N or 0° 7' 30\" W for latitude, and 0° 7' 30\" E or 120° 30' 0\" W for longitude. Degrees: integer 0-180 for longitude or 0-90 for latitude. Minutes: 0-59. Seconds: 0-59. Cardinal direction: N/S for latitude, E/W for longitude. The degree, minute, and second symbols are °, ', and \" respectively. Spaces between parts are optional but at most one.",
      "regex": "/^(?:90|\\d{1,2})° ?(?:[0-5]?\\d)' ?(?:[0-5]?\\d)\" ?[NS]$|^(?:180|\\d{1,2}|1[0-7]\\d)° ?(?:[0-5]?\\d)' ?(?:[0-5]?\\d)\" ?[EW]$/"
    },
    {
      "slot": 3,
      "description": "Match a temperature value with an optional sign, an integer or decimal number, and a unit either C or F. The unit can be upper or lower case. No space between number and unit.",
      "regex": "/^[+-]?\\d+(?:\\.\\d+)?[cC]$|^[+-]?\\d+(?:\\.\\d+)?[fF]$/"
    },
    {
      "slot": 4,
      "description": "We need to extract the width and height from product image specifications. The dimension string must be in the format widthxheight, where both are integers between 1 and 9999, and the separator is either a lowercase 'x' or an uppercase 'X'. There should be no leading zeros unless the number is zero itself, but zero is not allowed. Also, the width must be less than or equal to the height.",
      "regex": "/^(?<width>[1-9]\\d{0,3})[xX](?<height>[1-9]\\d{0,3})$/"
    },
    {
      "slot": 5,
      "description": "We need to validate longitude values entered by users in decimal degrees. The value must be between -180 and 180 inclusive. It can be an integer or have up to 6 decimal places. An optional minus sign is allowed. At most one digit before the decimal point is allowed if the integer part is 0, otherwise 1 to 3 digits.",
      "regex": "/^-?(?:180(?:\\.0{1,6})?|(?:\\d{1,3})(?:\\.\\d{1,6})?)$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "A valid product SKU consists of exactly 10 characters: the first two are uppercase letters (A-Z), the next six are digits (0-9), and the last two are uppercase letters (A-Z).",
      "regex": "/^[A-Z]{2}[0-9]{6}[A-Z]{2}$/"
    },
    {
      "slot": 2,
      "description": "64 hex chars lowercase sha256",
      "regex": "/^[0-9a-f]{64}$/"
    },
    {
      "slot": 3,
      "description": "A SHA-256 hash is a 64-character hexadecimal string. It can be uppercase or lowercase, but not a mix of both.",
      "regex": "/^(?:[0-9a-f]{64}|[0-9A-F]{64})$/"
    },
    {
      "slot": 4,
      "description": "UUID v4 lowercase",
      "regex": "/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/"
    },
    {
      "slot": 5,
      "description": "A version 4 UUID, case-insensitive, with hyphens in the usual places. The version character (first character of the third group) must be 4, and the variant character (first character of the fourth group) must be 8, 9, a, or b (case-insensitive).",
      "regex": "/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "In our analytics dashboard, we need to validate the path field that users enter for tracking internal pages. It must be a relative URL starting with a slash, followed by one or more non-slash characters, with optional subpaths each starting with a slash. No query strings or fragments allowed.",
      "regex": "/^\\/(?:[^/\\s]+\\/?)*$/"
    },
    {
      "slot": 2,
      "description": "Validate a domain name that belongs to the .co.uk top-level domain. A valid domain consists of one or more labels separated by dots, each label being 1 to 63 alphanumeric characters (letters, digits, hyphens) but not starting or ending with a hyphen. The domain must end with .co.uk. The entire string must be a valid domain, no subdomains allowed beyond the labels before .co.uk? Actually, it can have subdomains: the domain can have multiple labels before .co.uk, but each label must follow the rules.",
      "regex": "/^(?:(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)\\.)+(?:co\\.uk)$/"
    },
    {
      "slot": 3,
      "description": "Specification for HTTP/HTTPS URL validation:\n- Must start with \"http://\" or \"https://\" (case-insensitive).\n- Followed by a hostname: one or more domain labels separated by dots, each label 1-63 alphanumeric characters or hyphens, not starting or ending with hyphen.\n- Optionally followed by a port: a colon and between 1 and 5 digits.\n- Optionally followed by a path: a slash and any non-whitespace characters.\n- Optionally followed by a query string: a question mark and any non-whitespace characters.\n- Optionally followed by a fragment: a hash and any non-whitespace characters.\nNo other characters are allowed.",
      "regex": "/^https?:\\/\\/(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\\.)+[a-zA-Z]{2,}(?::\\d{1,5})?(?:\\/[^\\s]*)?(?:\\?[^\\s]*)?(?:#[^\\s]*)?$/i"
    },
    {
      "slot": 4,
      "description": "domain names ending in .io",
      "regex": "/^(?:(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)\\.)+io$/"
    },
    {
      "slot": 5,
      "description": "domain name ending with .com",
      "regex": "/^(?:(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)\\.)+com$/"
    }
  ]
}

{
  "items": [
