{
  "items": [
    {
      "slot": 1,
      "description": "A query string must consist of one or more key=value pairs separated by ampersands. Keys and values may contain any characters except ampersand and equals sign. Neither keys nor values may be empty. There must be no leading or trailing ampersand.",
      "regex": "/^[^&=]+=[^&=]+(&[^&=]+=[^&=]+)*$/"
    },
    {
      "slot": 2,
      "description": "A string is valid if it contains one or more integers separated by commas. Each integer is an optional minus sign followed by one or more digits. No spaces are allowed. There must be no leading or trailing comma.",
      "regex": "/^-?\\d+(,-?\\d+)*$/"
    },
    {
      "slot": 3,
      "description": "We need to verify that an authentication token looks like a JWT before sending it to the server. It must have exactly three parts separated by dots. The first two parts are Base64URL-encoded JSON objects, and the third is a Base64URL-encoded signature. Each part must be non-empty and contain only Base64URL characters (A-Z, a-z, 0-9, hyphen, underscore). Padding characters are not allowed.",
      "regex": "/^[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+$/"
    },
    {
      "slot": 4,
      "description": "A string is valid if it contains one or more key=value pairs separated by ampersands. Keys must start with a letter and may contain letters, digits, underscores, or hyphens. Values may contain any characters except ampersand and equals sign, but must not be empty and must not contain a double quote. There must be no leading or trailing ampersand.",
      "regex": "/^[A-Za-z][A-Za-z0-9_-]*=[^&=\"]+(&[A-Za-z][A-Za-z0-9_-]*=[^&=\"]+)*$/"
    },
    {
      "slot": 5,
      "description": "Our app receives a list of numeric sensor readings embedded in a string. The string must represent a JSON array of numbers. The array must contain one or more numbers, separated by commas, with optional whitespace around commas and brackets. Each number may be an integer or a decimal with an optional fractional part, and may have an optional leading minus sign.",
      "regex": "/^\\s*\\[\\s*-?\\d+(\\.\\d+)?(\\s*,\\s*-?\\d+(\\.\\d+)?)*\\s*\\]\\s*$/"
    }
  ]
}

{
