{
  "items": [
    {
      "slot": 1,
      "description": "Match an amount in Japanese yen. The amount must be a positive integer with no decimal part. Thousands may be separated by commas, but only if they are correctly placed: the first group has 1 to 3 digits, and every following group has exactly 3 digits. A leading comma is not allowed. A minus sign is not allowed. The string must contain only the number; currency symbols are not allowed.",
      "regex": "/^(?:[1-9]\\d{0,2}(?:,\\d{3})*|[0-9]\\d*)$/"
    },
    {
      "slot": 2,
      "description": "Match a euro price written in the French convention. It consists of the euro symbol (€) written after the amount. The amount uses a comma as the decimal separator and may have exactly two decimal digits; if no decimal part is present, the comma is omitted. The integer part may contain non-breaking spaces as thousands separators, but only if they are correctly placed: the first group has 1 to 3 digits, and every following group has exactly 3 digits. A leading separator is not allowed. Negative amounts and leading plus signs are not allowed. The string must consist solely of the amount and the euro symbol; spaces must not appear between the amount and the symbol.",
      "regex": "/^(?:[1-9]\\d{0,2}(?:\\u00A0\\d{3})*|0)(?:,\\d{2})?€$/u"
    },
    {
      "slot": 3,
      "description": "us dollar amount optional cents",
      "regex": "/^\\$(?:0|[1-9]\\d{0,2}(?:,\\d{3})*)(?:\\.\\d{2})?$/"
    },
    {
      "slot": 4,
      "description": "price with exactly two decimals",
      "regex": "/^(?:0|[1-9]\\d*)\\.\\d{2}$/"
    },
    {
      "slot": 5,
      "description": "We need to accept payments in Japanese yen in our checkout. The payment amount field should allow any whole number of yen from 0 up to and including 1,000,000, without decimal places. For readability, amounts may include commas as thousands separators, but they must be placed correctly. If a comma is used, the first group should have one to three digits, and every following group should have exactly three digits.",
      "regex": "/^(?:0|[1-9]\\d{0,2}(?:,\\d{3})*|1000000|1,000,000)$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "A string representing a weight measurement in kilograms or grams.\nRules:\n1. Optional leading/trailing whitespace is allowed (spaces only).\n2. The value is a number: one or more digits, optionally followed by a decimal point and exactly two digits (e.g., '1.50'). A leading plus sign is allowed.\n3. The unit is 'kg' for kilograms or 'g' for grams, case-insensitive.\n4. At least one space must separate the number and the unit.",
      "regex": "/^\\s*\\+?\\d+(\\.\\d{2})?\\s+[kK][gG]\\s*$|^\\s*\\+?\\d+(\\.\\d{2})?\\s+[gG]\\s*$/"
    },
    {
      "slot": 2,
      "description": "We need to validate the screen resolution field in our device management console. The field accepts width and height in pixels, separated by a lowercase 'x' or uppercase 'X'. Both width and height must be integers between 320 and 7680 inclusive.",
      "regex": "/^(?:3[2-9]\\d|[4-9]\\d{2}|[1-6]\\d{3}|7[0-5]\\d{2}|76[0-7]\\d|7680)[xX](?:3[2-9]\\d|[4-9]\\d{2}|[1-6]\\d{3}|7[0-5]\\d{2}|76[0-7]\\d|7680)$/"
    },
    {
      "slot": 3,
      "description": "Our cloud storage dashboard shows file sizes in KB, MB, or GB. The value is a positive integer followed by a space and one of those units, case-insensitive. For example, '500 KB' or '1.5 GB'? No, only whole numbers, no decimals. Also, the number must be between 1 and 1024 for KB and MB, and between 1 and 1000 for GB.",
      "regex": "/^(?:[1-9]\\d{0,2}|102[0-4])\\s+[kK][bB]$|^(?:[1-9]\\d{0,2}|102[0-4])\\s+[mM][bB]$|^(?:[1-9]\\d{0,2}|1000)\\s+[gG][bB]$/"
    },
    {
      "slot": 4,
      "description": "Validate a coordinate in degrees, minutes, and seconds (DMS) format. The coordinate consists of:\n- Degrees: an integer from 0 to 180 for longitude or 0 to 90 for latitude? Wait, both latitude and longitude share the same format. Actually, the format is: degrees (0-180), minutes (0-59), seconds (0-59), followed by a hemisphere letter (N, S, E, or W).\n- The components are separated by spaces or degree/minute/second symbols? Let's use symbols: ° for degrees, ′ for minutes, ″ for seconds. However, these are optional; if omitted, a space is required.\n- The final hemisphere letter is mandatory and must be one of N, S, E, W (case insensitive).\n- Leading zeros are allowed for minutes and seconds but not required.\n- No decimal places in seconds.\n\nExamples (not to be included in the description, but for clarity): 45°30′15″N, 120 45 30 E, 90°0′0″S.",
      "regex": "/^(?:180|1[0-7]\\d|[0-9]?\\d)°?\\s*(?:[0-5]?\\d)′?\\s*(?:[0-5]?\\d)″?\\s*[NSEWnsew]$/"
    },
    {
      "slot": 5,
      "description": "A temperature value with a unit, either Celsius or Fahrenheit. The value can be a positive or negative integer or decimal number. The unit is 'C' or 'F', and may be preceded by a degree symbol and/or a space.",
      "regex": "/^[+-]?\\d+(?:\\.\\d+)?\\s*°?\\s*[CcFf]$/"
    }
  ]
}

