{
  "items": [
    {
      "slot": 1,
      "description": "We need to validate the mobile phone number field in our UK signup form. Only UK mobile numbers are accepted. The format should be either national or international, but not both mixed. National format must start with 07, followed by exactly 9 digits, and may optionally include spaces between digit groups. International format must start with +44, followed by the national number without the leading 0, i.e., 7 followed by 9 digits, and may optionally include spaces. No other characters are allowed except spaces as separators.",
      "regex": "/^(?:\\+44\\s?7\\d{3}\\s?\\d{6}|07\\d{3}\\s?\\d{6})$/"
    },
    {
      "slot": 2,
      "description": "The input must be a North American phone number. It must consist of a 3-digit area code, a 3-digit central office code, and a 4-digit line number, in that order. The area code and central office code cannot start with 0 or 1. The number may be formatted with optional separators: a hyphen, a space, or a dot between the area code and central office code, and between the central office code and line number. The separators must be consistent: if a hyphen is used between the first two groups, a hyphen must also be used between the last two groups; similarly for space or dot. Alternatively, no separators may be used at all. The number may optionally be preceded by '1' followed by a space or hyphen, or no separator before the area code. The number may optionally be enclosed in parentheses around the area code, but if parentheses are used, the area code must be immediately followed by a space or hyphen, and the rest of the number must follow the separator consistency rule for the remaining groups.",
      "regex": "/^(?:1[\\s-]?)?(?:\\(([2-9]\\d{2})\\)[\\s-]?|([2-9]\\d{2})([\\s.-]?))([2-9]\\d{2})\\4(\\d{4})$/"
    },
    {
      "slot": 3,
      "description": "Match a phone number that may optionally start with a country code. The country code, if present, is a plus sign followed by one to three digits. After the optional country code, there must be a sequence of digits, optionally grouped by spaces or hyphens. The total number of digits (excluding the country code) must be between 6 and 14. The groups can be of any length but must be separated by a single space or hyphen, and the string cannot start or end with a separator. If a country code is present, it must be directly followed by a digit or a space/hyphen then a digit.",
      "regex": "/^(?:\\+\\d{1,3}[\\s-]?)?\\d{1,4}(?:[\\s-]?\\d{1,4}){5,13}$/"
    },
    {
      "slot": 4,
      "description": "We need to validate international phone numbers for our global SMS service. The number may optionally start with a plus sign followed by a country code (1 to 3 digits). After that, the national number should be 7 to 12 digits, possibly with spaces for readability. Spaces can appear between any digits but not at the beginning or end. The total number of digits (including country code if present) must be between 8 and 15. Also, if a plus sign is present, it must be immediately followed by a digit.",
      "regex": "/^(?:\\+\\d{1,3})?\\d{1,12}(?:\\s?\\d{1,12}){6,11}$/"
    },
    {
      "slot": 5,
      "description": "Validate a French mobile phone number. It must be exactly 10 digits, starting with 0, then 6 or 7, followed by 8 digits. Spaces are allowed between pairs of digits (e.g., after the second, fourth, sixth, and eighth digits), but not at the beginning or end, and not more than one space in a row.",
      "regex": "/^0[67](?:\\s?\\d{2}){4}$/"
    }
  ]
}

{
