      "regex": "/^\\d+\\.\\d+\\.\\d+(?:-[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?(?:\\+[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?$/"
    },
    {
      "slot": 2,
      "description": "A Python version specifier consists of an operator followed by a version number. The operator can be one of ==, !=, <=, >=, <, >, ~=, or ===. The version number is a dot-separated list of numeric components, optionally followed by a pre-release segment and/or a local version segment. The pre-release segment starts with a hyphen and consists of dot-separated identifiers. The local version segment starts with a plus sign and consists of dot-separated identifiers. Identifiers are alphanumeric strings that may contain hyphens and underscores.",
      "regex": "/^(?:===|==|!=|<=|>=|<|>|~=)\\d+(?:\\.\\d+)*(?:-[0-9A-Za-z.-]+)?(?:\\+[0-9A-Za-z_.-]+)?$/"
    },
    {
      "slot": 3,
      "description": "A semantic version string consists of three numeric components separated by periods: major, minor, and patch. Each component is a non-negative integer without leading zeros, except that the number zero itself is allowed. The version may optionally be followed by a pre-release segment that starts with a hyphen and consists of one or more dot-separated identifiers; each identifier may contain ASCII alphanumeric characters and hyphens, and numeric identifiers must not have leading zeros unless the identifier is just zero. The version may also optionally be followed by a build metadata segment that starts with a plus sign and consists of one or more dot-separated identifiers; each identifier may contain ASCII alphanumeric characters and hyphens, and numeric identifiers may have leading zeros. The pre-release and build metadata segments are independent: either, both, or neither may be present, but if both are present the pre-release must come first.",
      "regex": "/^(?:0|[1-9]\\d*)\\.(?:0|[1-9]\\d*)\\.(?:0|[1-9]\\d*)(?:-(?:(?:0|[1-9]\\d*)|(?:\\d*[A-Za-z-][0-9A-Za-z-]*))(?:\\.[0-9A-Za-z-]+)*)?(?:\\+[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?$/"
    },
    {
      "slot": 4,
      "description": "calendar version like 2024.06",
      "regex": "/^\\d{4}\\.\\d{2}$/"
    },
