      "regex": "/^[~^](?:0|[1-9]\\d*)\\.(?:0|[1-9]\\d*)\\.(?:0|[1-9]\\d*)(?:-[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?(?:\\+[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?$/"
    },
    {
      "slot": 5,
      "description": "semver x.y.z with optional -prerelease and +build, prerelease dot-separated alnum ids, build dot-separated alnum ids",
      "regex": "/^(?:0|[1-9]\\d*)\\.(?:0|[1-9]\\d*)\\.(?:0|[1-9]\\d*)(?:-[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?(?:\\+[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "A string that starts and ends with the same quote character, either a double quote or a single quote, with any characters in between except the quote character that started it.",
      "regex": "/^(\"([^\"\\n]*)\"|'([^'\\n]*)')$/"
