      "regex": "/^((?:\\d{1,3}\\.){3}\\d{1,3}|[0-9A-Fa-f:]+)(?:, (?:\\d{1,3}\\.){3}\\d{1,3})* \\[(?:\\d{2})\\/(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\\/(?:\\d{4}):(?:\\d{2}):(?:\\d{2}):(?:\\d{2}) [+-]\\d{4}\\] \"(?:[A-Z]+) (?:(?:\\S+)) HTTP\\/\\d+\\.\\d+\" \\d{3} (?:\\d+|-)$/"
