      "slot": 1,
      "description": "A valid file name must satisfy all of the following rules:\n- Length is between 1 and 255 characters.\n- Must not contain any of these characters: / \\ : * ? \" < > | or the null character.\n- Must not be a reserved device name (case-insensitive): CON, PRN, AUX, NUL, COM1 through COM9, LPT1 through LPT9.\n- Must not start or end with a space or a dot.\n- Must not consist solely of dots.",
      "regex": "/^(?!(?:CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])$)(?!\\.+$)[^\\/\\\\:*?\"<>|\\x00][^\\/\\\\:*?\"<>|\\x00]{0,253}[^\\/\\\\:*?\"<>|\\x00]$|^[^\\/\\\\:*?\"<>|\\x00]$/i"
    },
    {
      "slot": 2,
      "description": "Our build tool needs to identify test files so it can run them separately. A test file is any file whose name matches one of these patterns, in any combination of upper and lower case:\n- The base name ends with .spec or .test, followed by one of these JavaScript/TypeScript extensions: .js, .jsx, .ts, or .tsx.\n- The base name ends with .spec or .test, followed by .d.ts (TypeScript declaration test).",
      "regex": "/^.*\\.(spec|test)\\.(js|jsx|ts|tsx)$|^.*\\.(spec|test)\\.d\\.ts$/i"
    },
    {
      "slot": 3,
      "description": "A test file name must end with one of the following, case-insensitive: .spec.js, .spec.jsx, .spec.ts, .spec.tsx, .test.js, .test.jsx, .test.ts, .test.tsx, .spec.d.ts, or .test.d.ts. No other characters are allowed before the final suffix.",
      "regex": "/^.*\\.(spec|test)\\.(js|jsx|ts|tsx)$|^.*\\.(spec|test)\\.d\\.ts$/i"
    },
    {
      "slot": 4,
      "description": "A file name with a date prefix should start with a date in YYYY-MM-DD format, followed by a hyphen, and then any valid file name characters (letters, digits, underscores, hyphens, and dots). The date is just a format, no calendar validation is needed.",
      "regex": "/^\\d{4}-\\d{2}-\\d{2}-[A-Za-z0-9_.-]+$/"
    },
    {
      "slot": 5,
      "description": "The file name must meet all these criteria:\n- Length between 1 and 255 characters.\n- Must not contain any of the following forbidden characters: / \\ : * ? \" < > | or the null character.\n- Must not be a reserved name (case-insensitive): CON, PRN, AUX, NUL, COM1–COM9, LPT1–LPT9.\n- Must not start or end with a space or a period.\n- Must not consist only of periods.",
      "regex": "/^(?!(?:CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])$)(?!\\.+$)[^\\/\\\\:*?\"<>|\\x00][^\\/\\\\:*?\"<>|\\x00]{0,253}[^\\/\\\\:*?\"<>|\\x00]$|^[^\\/\\\\:*?\"<>|\\x00]$/i"
    }
  ]
}

