    },
    {
      "slot": 3,
      "description": "A line in the common Apache or nginx access log format. It consists of the client IP address, an optional identd, an optional authenticated user, a timestamp in square brackets, a quoted request line, a numeric status code, and a byte count. Fields are separated by single spaces; the client IP is a standard dotted-decimal IPv4 address or an IPv6 address.",
      "regex": "/^(?:(?:\\d{1,3}\\.){3}\\d{1,3}|[0-9A-Fa-f:]+) \\S+ \\S+ \\[\\d{2}\\/[A-Za-z]{3}\\/\\d{4}:\\d{2}:\\d{2}:\\d{2} [+-]\\d{4}\\] \"[^\"]*\" \\d{3} \\d+$/"
    },
    {
