    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "Our monitoring dashboard filters log excerpts and must flag any line that mentions an error code. We consider a line flagged if it contains the standalone token ERR followed by a hyphen and exactly four decimal digits, and that token must not be part of a longer alphanumeric word. The text may appear anywhere in the line, and the match is case-sensitive, so only uppercase ERR is recognized.",
      "regex": "/(?<![A-Za-z0-9])ERR-\\d{4}(?![A-Za-z0-9])/"
    },
    {
      "slot": 2,
      "description": "Detect a line that contains a JavaScript stack trace frame. Such a frame starts with the word \"at\", followed by a space, and includes a file path ending with .js and a location in parentheses. We only need to know whether any such frame appears anywhere on the line, not the whole line.",
      "regex": "/\\bat .+\\.js \\([^)]*\\)/"
    },
    {
      "slot": 3,
      "description": "Detect a line that contains a Python stack trace frame. The frame starts with the word \"File\", followed by a space, an opening double quote, a file path ending with .py, a closing double quote, a comma, a space, the word \"line\", a space, a line number, and a trailing comma. The file path must not be empty and may include directories separated by slashes. The match should occur anywhere on the line and is case-sensitive.",
      "regex": "/\\bFile \"[^\"]+\\.py\", line \\d+,/"
    },
    {
      "slot": 4,
      "description": "We need to parse HTTP status lines in access logs. A valid status line must start at the beginning of the line with the sequence \"HTTP/\", followed by the version digits 1.0, 1.1, or 2 (as \"2\", not \"2.0\"), then a single space, then a three-digit status code that is either a 4xx or 5xx code (i.e., the first digit must be 4 or 5, and the remaining two digits can be any digits), then a single space, and then a reason phrase consisting of one or more characters that are not line breaks. The entire line must match this format, with no extra trailing characters.",
      "regex": "/^HTTP\\/(?:1\\.[01]|2) [45]\\d{2} [^\\r\\n]+$/"
    },
    {
      "slot": 5,
      "description": "Our performance team reviews server logs and needs to quickly spot lines where a request took longer than one second. A duration is written as a whole or decimal number followed immediately by either \"ms\" (milliseconds) or \"s\" (seconds), and it may appear anywhere in the line. We want to flag any line that contains at least one such duration that represents more than 1000 milliseconds, without matching other numbers in the line. Durations in seconds are considered above one second only if the number is strictly greater than 1. Durations in milliseconds are above one second only if the number is strictly greater than 1000. Numbers may have an optional fractional part; for example, 1000.1 ms is above one second, while 1000 ms and 1 s are not. The duration units are case-sensitive.",
      "regex": "/(?<![\\d.])(?:(?:\\d{4,}|(?:[2-9]\\d{2}|1\\d{3})\\d*)(?:\\.\\d+)? ms|(?:[2-9]\\d*|1\\d+)(?:\\.\\d+)? s|1\\.\\d*[1-9]\\d* s|0\\.\\d*[1-9]\\d* s|1000\\.\\d*[1-9]\\d* ms)(?![\\d.])/"
    }
  ]
}

