    {
      "slot": 2,
      "description": "conventional commit title",
      "regex": "/^(build|chore|ci|docs|feat|fix|perf|refactor|revert|style|test)(\\([a-z0-9-]+\\))?!?: .+$/"
    },
    {
      "slot": 3,
      "description": "We need to enforce a standard naming scheme for branches in our new project repository so that our CI/CD pipeline can trigger correctly based on branch type. Branch names should begin with a type indicator from this list: feature, bugfix, hotfix, release, or chore, followed by a forward slash, then a short description. The short description must be all lowercase letters, digits, and hyphens, with no consecutive hyphens and not starting or ending with a hyphen.",
      "regex": "/^(feature|bugfix|hotfix|release|chore)\\/[a-z0-9]+(?:-[a-z0-9]+)*$/"
    },
    {
      "slot": 4,
      "description": "A semantic pull request title consists of a type, an optional scope, an optional breaking-change marker, and a subject, optionally preceded by a ticket key. Valid examples follow this structure: [TICKET-123] type(scope)!: subject. The ticket key is optional and, if present, is a sequence of uppercase letters, a hyphen, and digits, enclosed in square brackets, followed by a space. The type is one of feat, fix, docs, style, refactor, perf, test, build, ci, chore, or revert. The scope is optional and, when present, appears in parentheses immediately after the type and must be lowercase alphanumeric words separated by hyphens. The breaking-change marker is an optional exclamation mark immediately after the scope (or type if no scope). A colon and a space must follow the type/scope/marker. The subject must contain at least one character and must not start or end with whitespace; it may contain any printable characters except newlines.",
      "regex": "/^(?:\\[[A-Z]+-\\d+\\] )?(feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert)(?:\\([a-z0-9]+(?:-[a-z0-9]+)*\\))?!?: \\S(?:.*\\S)?$/"
    },
    {
      "slot": 5,
      "description": "A simplified five-field cron expression must satisfy these constraints: the five fields are minute, hour, day of month, month, and day of week, in that order, separated by single spaces. Minute: 0–59. Hour: 0–23. Day of month: 1–31. Month: 1–12. Day of week: 0–6, where 0 is Sunday. Each field accepts a single number, a comma-separated list of numbers, a range of two numbers separated by a hyphen (inclusive), a step value across a range or a wildcard (e.g., */n or a-b/n), or a wildcard (*). A step value is a forward slash followed by a positive integer no greater than the field's maximum. Ranges must be in ascending order and within the field's bounds. Lists must contain at least one item and items must not be empty. No field name or special macros are allowed. The entire expression must be exactly five fields.",
      "regex": "/^(?:(?:\\*|(?:[0-5]?\\d)(?:-(?:[0-5]?\\d))?(?:\\/(?:[1-9]|[1-5]\\d))?(?:,(?:[0-5]?\\d)(?:-(?:[0-5]?\\d))?(?:\\/(?:[1-9]|[1-5]\\d))?)*|\\*\\/(?:[1-9]|[1-5]\\d))|(?:[01]?\\d|2[0-3])(?:-(?:[01]?\\d|2[0-3]))?(?:\\/(?:[1-9]|[12]\\d|3[0-1]))?(?:,(?:[01]?\\d|2[0-3])(?:-(?:[01]?\\d|2[0-3]))?(?:\\/(?:[1-9]|[12]\\d|3[0-1]))?)*|\\*\\/(?:[1-9]|[12]\\d|3[0-1]))|(?:[1-9]|[12]\\d|3[01])(?:-(?:[1-9]|[12]\\d|3[01]))?(?:\\/(?:[1-9]|[12]\\d|3[0-1]))?(?:,(?:[1-9]|[12]\\d|3[01])(?:-(?:[1-9]|[12]\\d|3[01]))?(?:\\/(?:[1-9]|[12]\\d|3[0-1]))?)*|\\*\\/(?:[1-9]|[12]\\d|3[0-1]))|(?:[1-9]|1[0-2])(?:-(?:[1-9]|1[0-2]))?(?:\\/(?:[1-9]|1[0-2]))?(?:,(?:[1-9]|1[0-2])(?:-(?:[1-9]|1[0-2]))?(?:\\/(?:[1-9]|1[0-2]))?)*|\\*\\/(?:[1-9]|1[0-2]))|(?:[0-6])(?:-(?:[0-6]))?(?:\\/(?:[1-6]))?(?:,(?:[0-6])(?:-(?:[0-6]))?(?:\\/(?:[1-6]))?)*|\\*\\/(?:[1-6]))$/"
