      "slot": 1,
      "description": "Validate a semantic pull request title that must start with a conventional commit type in parentheses, followed by a colon and a space, then a ticket key in square brackets like [ABC-123], then a space and a non-empty description. The type must be one of feat, fix, docs, style, refactor, perf, test, build, ci, chore, or revert, in lowercase. The ticket key must be two or more uppercase letters, a hyphen, and one or more digits.",
      "regex": "/^(feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert): \\[[A-Z]{2,}-\\d+\\] .+$/"
    },
