      "regex": "/^(?:\\*|(?:[0-5]?\\d)(?:,(?:[0-5]?\\d))*)\\s+(?:\\*|(?:1?\\d|2[0-3])(?:,(?:1?\\d|2[0-3]))*)\\s+(?:\\*|(?:[1-9]|[12]\\d|3[01])(?:,(?:[1-9]|[12]\\d|3[01]))*)\\s+(?:\\*|(?:[1-9]|1[0-2])(?:,(?:[1-9]|1[0-2]))*)\\s+(?:\\*|[0-7](?:,[0-7])*)$/"
    },
    {
      "slot": 3,
      "description": "We need to validate cron expressions in our scheduling UI. The expression must have exactly five fields separated by spaces: minute (0-59), hour (0-23), day of month (1-31), month (1-12), and day of week (0-7). Each field can be a single number or an asterisk to mean 'every'. Only these simple forms are allowed—no ranges, lists, or step values.",
      "regex": "/^(?:\\*|(?:[0-5]?\\d))\\s+(?:\\*|(?:1?\\d|2[0-3]))\\s+(?:\\*|(?:[1-9]|[12]\\d|3[01]))\\s+(?:\\*|(?:[1-9]|1[0-2]))\\s+(?:\\*|[0-7])$/"
    },
    {
      "slot": 4,
      "description": "Validate a semantic pull request title that must start with a conventional commit type in parentheses, followed by an optional scope in parentheses, then a colon and a space, then a ticket key in square brackets like [ABC-123], then a space and a non-empty description. The type must be one of feat, fix, docs, style, refactor, perf, test, build, ci, chore, or revert, in lowercase. The scope, if present, must be a lowercase word (letters, digits, hyphen, underscore). The ticket key must be two or more uppercase letters, a hyphen, and one or more digits. The description must not contain any uppercase letters, and must not start with a space or contain double spaces.",
      "regex": "/^(feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert)(?:\\([a-z0-9_-]+\\))?: \\[[A-Z]{2,}-\\d+\\] (?=[^A-Z]*$)(?!.*  )\\S(?:.*\\S)?$/"
