      "slot": 1,
      "description": "A multi-line string is valid if at least one of its lines starts with the hash symbol as its very first character. The hash must be followed by any content (possibly empty). Lines are allowed to be empty and the input may end with a newline; using start-of-line anchor with the multiline flag is expected, but the hash is only a start-of-line character if it is the first character of a line.",
      "regex": "/^#/m"
    },
    {
      "slot": 2,
      "description": "no line may end with a space or tab; a final newline at the end of the text is not considered trailing whitespace",
      "regex": "/^(?![\\s\\S]*?[ \\t](?:\\r?\\n|$))[\\s\\S]*$/"
    },
    {
      "slot": 3,
      "description": "The text must consist of at most three lines. A trailing newline at the very end does not create an extra line and is allowed; apart from that, lines are separated by newline characters and may contain any characters. The empty string counts as having zero lines.",
      "regex": "/^(?:[^\\n]*(?:\\n[^\\n]*){0,2})?\\n?$/s"
    },
    {
      "slot": 4,
      "description": "at most 3 lines, trailing newline allowed",
      "regex": "/^(?:[^\\n]*\\n?){0,3}$/"
    },
    {
      "slot": 5,
      "description": "A multi-line string is valid when every line consists of one or more decimal digits. An optional single trailing newline at the end of the string is permitted. Empty lines, leading zeros, and non-digit characters are not allowed.",
      "regex": "/^\\d+(?:\\n\\d+)*\\n?$/"
    }
  ]
}

