      "regex": "/(?<!\\S)(?:(?:[1-9]\\d{0,2}|0)\\.\\d+|(?:(?!1(?:\\.0+)?s(?!\\w))[1-9]\\d{0,2})(?:\\.\\d+)?)s(?!\\w)/"
