      "regex": "/^(?:(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\\.)*[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\\/)?(?:[a-z0-9]+(?:(?:\\.|_|__|-+)[a-z0-9]+)*\\/)*[a-z0-9]+(?:(?:\\.|_|__|-+)[a-z0-9]+)*(?::\\w[\\w.-]{0,127})?$/",
