}

{
  "items": [
    {
      "slot": 1,
      "description": "Match an HTTP status line that starts with the protocol version HTTP/1.1, a space, a three-digit status code that is either 4xx or 5xx, a space, and a reason phrase of one or more printable characters. The status code must be exactly three digits and the first digit must be 4 or 5.",
      "regex": "/^HTTP\\/1\\.1 (?:4|5)\\d{2} .+$/i"
    },
    {
      "slot": 2,
      "description": "match an apache or nginx combined log line: ipv4, ident, user, timestamp, request, status, bytes, referer, user agent; allow user to be - and bytes to be -",
      "regex": "/^\\d{1,3}(?:\\.\\d{1,3}){3} \\S+ \\S+ \\[[^\\]]+\\] \"[^\"]*\" \\d{3} (?:\\d+|-)(?: \"[^\"]*\" \"[^\"]*\")?$/"
    },
    {
      "slot": 3,
      "description": "Match a line that mentions a duration greater than one second. Durations are written as a number immediately followed by ms (milliseconds), s (seconds), or m (minutes). Only durations strictly greater than 1000 milliseconds, 1 second, or 1 minute count. The number may have a decimal part separated by a dot.",
      "regex": "/\\b(?:\\d+(?:\\.\\d+)?(?:m|s)|(?:\\d{4,}|\\d{1,3}(?:\\.\\d+)?)ms)\\b/i"
    },
    {
      "slot": 4,
      "description": "We are building a dashboard that flags slow requests. Our log lines contain a field like 'duration=1.5s' or 'duration=200ms'. We want to highlight any request that took longer than one second. Only the format of the duration and the fact that it exceeds one second matter; the line may contain other text.",
      "regex": "/duration=(?:(?:\\d+(?:\\.\\d+)?(?:m|s))|(?:\\d{4,}|\\d{1,3}(?:\\.\\d+)?)ms)\\b/i"
    },
    {
      "slot": 5,
      "description": "A log line is valid if it contains an error code. An error code is the letter E followed by exactly three digits, for example E123. The code must be surrounded by word boundaries.",
      "regex": "/\\bE\\d{3}\\b/"
    }
  ]
}

